-- membuang struktur untuk table mutu.mutu_audit
CREATE TABLE IF NOT EXISTS `mutu_audit` (
  `audit_id` int(11) NOT NULL AUTO_INCREMENT,
  `form_id` int(11) NOT NULL,
  `auditee` varchar(60) NOT NULL,
  `auditee_id` int(11) NOT NULL,
  `auditor` varchar(40) NOT NULL,
  `auditor_id` int(11) NOT NULL,
  `unit` varchar(40) NOT NULL,
  `audit_status` enum('DRAFT','TERKIRIM','PROSES','SELESAI') NOT NULL DEFAULT 'DRAFT',
  `audit_create` timestamp NOT NULL DEFAULT current_timestamp(),
  `audit_update` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `periode_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`audit_id`),
  KEY `form_id` (`form_id`),
  KEY `auditee_id` (`auditee_id`),
  KEY `auditor_id` (`auditor_id`),
  CONSTRAINT `audit_auditee_id` FOREIGN KEY (`auditee_id`) REFERENCES `mutu_users` (`users_id`),
  CONSTRAINT `audit_auditor_id` FOREIGN KEY (`auditor_id`) REFERENCES `mutu_users` (`users_id`),
  CONSTRAINT `audit_form_id` FOREIGN KEY (`form_id`) REFERENCES `mutu_formulir` (`form_id`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

