 <w:LsdException Locked="false" Priority="47" Name="List Table 2 Accent 2"/>\n  <w:LsdException Locked="false" Priority="48" Name="List Table 3 Accent 2"/>\n  <w:LsdException Locked="false" Priority="49" Name="List Table 4 Accent 2"/>\n  <w:LsdException Locked="false" Priority="50" Name="List Table 5 Dark Accent 2"/>\n  <w:LsdException Locked="false" Priority="51"\n   Name="List Table 6 Colorful Accent 2"/>\n  <w:LsdException Locked="false" Priority="52"\n   Name="List Table 7 Colorful Accent 2"/>\n  <w:LsdException Locked="false" Priority="46"\n   Name="List Table 1 Light Accent 3"/>\n  <w:LsdException Locked="false" Priority="47" Name="List Table 2 Accent 3"/>\n  <w:LsdException Locked="false" Priority="48" Name="List Table 3 Accent 3"/>\n  <w:LsdException Locked="false" Priority="49" Name="List Table 4 Accent 3"/>\n  <w:LsdException Locked="false" Priority="50" Name="List Table 5 Dark Accent 3"/>\n  <w:LsdException Locked="false" Priority="51"\n   Name="List Table 6 Colorful Accent 3"/>\n  <w:LsdException Locked="false" Priority="52"\n   Name="List Table 7 Colorful Accent 3"/>\n  <w:LsdException Locked="false" Priority="46"\n   Name="List Table 1 Light Accent 4"/>\n  <w:LsdException Locked="false" Priority="47" Name="List Table 2 Accent 4"/>\n  <w:LsdException Locked="false" Priority="48" Name="List Table 3 Accent 4"/>\n  <w:LsdException Locked="false" Priority="49" Name="List Table 4 Accent 4"/>\n  <w:LsdException Locked="false" Priority="50" Name="List Table 5 Dark Accent 4"/>\n  <w:LsdException Locked="false" Priority="51"\n   Name="List Table 6 Colorful Accent 4"/>\n  <w:LsdException Locked="false" Priority="52"\n   Name="List Table 7 Colorful Accent 4"/>\n  <w:LsdException Locked="false" Priority="46"\n   Name="List Table 1 Light Accent 5"/>\n  <w:LsdException Locked="false" Priority="47" Name="List Table 2 Accent 5"/>\n  <w:LsdException Locked="false" Priority="48" Name="List Table 3 Accent 5"/>\n  <w:LsdException Locked="false" Priority="49" Name="List Table 4 Accent 5"/>\n  <w:LsdException Locked="false" Priority="50" Name="List Table 5 Dark Accent 5"/>\n  <w:LsdException Locked="false" Priority="51"\n   Name="List Table 6 Colorful Accent 5"/>\n  <w:LsdException Locked="false" Priority="52"\n   Name="List Table 7 Colorful Accent 5"/>\n  <w:LsdException Locked="false" Priority="46"\n   Name="List Table 1 Light Accent 6"/>\n  <w:LsdException Locked="false" Priority="47" Name="List Table 2 Accent 6"/>\n  <w:LsdException Locked="false" Priority="48" Name="List Table 3 Accent 6"/>\n  <w:LsdException Locked="false" Priority="49" Name="List Table 4 Accent 6"/>\n  <w:LsdException Locked="false" Priority="50" Name="List Table 5 Dark Accent 6"/>\n  <w:LsdException Locked="false" Priority="51"\n   Name="List Table 6 Colorful Accent 6"/>\n  <w:LsdException Locked="false" Priority="52"\n   Name="List Table 7 Colorful Accent 6"/>\n  <w:LsdException Locked="false" SemiHidden="true" UnhideWhenUsed="true"\n   Name="Mention"/>\n  <w:LsdException Locked="false" SemiHidden="true" UnhideWhenUsed="true"\n   Name="Smart Hyperlink"/>\n  <w:LsdException Locked="false" SemiHidden="true" UnhideWhenUsed="true"\n   Name="Hashtag"/>\n  <w:LsdException Locked="false" SemiHidden="true" UnhideWhenUsed="true"\n   Name="Unresolved Mention"/>\n  <w:LsdException Locked="false" SemiHidden="true" UnhideWhenUsed="true"\n   Name="Smart Link"/>\n </w:LatentStyles>\n</xml><![endif]--><!--[if gte mso 10]>\n<style>\n /* Style Definitions */\n table.MsoNormalTable\n	{mso-style-name:"Table Normal";\n	mso-tstyle-rowband-size:0;\n	mso-tstyle-colband-size:0;\n	mso-style-noshow:yes;\n	mso-style-priority:99;\n	mso-style-parent:"";\n	mso-padding-alt:0cm 5.4pt 0cm 5.4pt;\n	mso-para-margin-top:0cm;\n	mso-para-margin-right:0cm;\n	mso-para-margin-bottom:8.0pt;\n	mso-para-margin-left:0cm;\n	line-height:107%;\n	mso-pagination:widow-orphan;\n	font-size:11.0pt;\n	mso-bidi-font-size:14.0pt;\n	font-family:"Calibri",sans-serif;\n	mso-ascii-font-family:Calibri;\n	mso-ascii-theme-font:minor-latin;\n	mso-hansi-font-family:Calibri;\n	mso-hansi-theme-font:minor-latin;\n	mso-bidi-font-family:"Cordia New";\n	mso-bidi-theme-font:minor-bidi;\n	mso-font-kerning:1.0pt;\n	mso-ligatures:standardcontextual;\n	mso-fareast-language:EN-US;\n	mso-bidi-language:TH;}\n</style>\n<![endif]-->\n\n<p class="MsoNormal"><span style="font-size: 12px;">1. Penerapan prinsip pengembangan struktur kurikulum pada\nProgram Studi Diploma Tiga (D-III) Keperawatan didasarkan pada panduan nasional\npendidikan tinggi kesehatan dan kebutuhan kompetensi profesi perawat vokasi\nberdasarkan KKNI Level 5,</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal"><span style="font-size: 12px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;a.&nbsp;&nbsp;</span><b><span style="font-size: 12px;">Berbasis\nCapaian Pembelajaran Lulusan (CPL)</span></b></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal"><span style="font-size: 12px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\n&nbsp;Struktur kurikulum disusun </span><b><span style="font-size: 12px;">berdasarkan CPL</span></b><span style="font-size: 12px;"> yang telah dirumuskan\nmengacu pada </span><b><span style="font-size: 12px;">KKNI&nbsp; </span></b></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal"><b><span style="font-size: 12px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\n&nbsp;level 5</span></b><span style="font-size: 12px;"> dan </span><b><span style="font-size: 12px;">Standar Nasional Pendidikan Tinggi (SN-Dikti)</span></b><span style="font-size: 12px;">.</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal" style="margin-left: 25px;"><span style="font-size: 12px;">b. Keseimbangan antara teori dan praktik</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal" style="margin-left: 25px;"><span style="font-size: 12px;">c. Penerapan Kurikulum berbasis OBE</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal" style="margin-left: 25px;"><span style="font-size: 12px;">d. Relevansi dengan kebutuhan stakeholders</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal"><span style="font-size: 12px;">&nbsp;</span></p><span style="font-size: 12px;">\n\n</span><p class="MsoNormal"><span style="font-size: 12px;">2.&nbsp;Kurikulum Program Studi Diploma Tiga Keperawatan\ndirancang secara integratif dengan memperhatikan keterkaitan berbagai disiplin\nilmu yang membentuk kompetensi perawat vokasi secara utuh. Struktur kurikulum\nmenggabungkan ilmu dasar, ilmu biomedik, ilmu perilaku, serta ilmu keperawatan\nklinik dan manajemen, yang saling mendukung untuk menghasilkan lulusan yang\nkompeten, profesional, dan beretika. Ilmu dasar umum seperti Bahasa Indonesia,\nPendidikan Agama, dan Pancasila berperan dalam membentuk karakter, moral, dan\nkemampuan komunikasi mahasiswa. Ilmu biomedik dasar seperti anatomi, fisiologi,\nmikrobiologi, patofisiologi, dan farmakologi memberikan dasar ilmiah bagi\npemahaman kondisi kesehatan dan penyakit, yang menjadi pijakan dalam\npelaksanaan asuhan keperawatan. Sementara itu, ilmu perilaku dan sosial seperti\npsikologi, sosiologi, dan komunikasi terapeutik memperkuat kemampuan mahasiswa\ndalam memahami perilaku manusia, berinteraksi dengan pasien, serta membangun\nhubungan terapeutik yang efektif. Selanjutnya,&nbsp; keperawatan dasar dan\nkeperawatan klinik (keperawatan medikal bedah, maternitas, anak, jiwa, dan\nkomunitas) mengintegrasikan seluruh pengetahuan biomedik dan perilaku ke dalam\nkonteks praktik nyata. Mahasiswa belajar memberikan asuhan keperawatan secara\nholistik berdasarkan proses keperawatan dan prinsip keselamatan pasien.\nDisiplin manajemen dan etika keperawatan juga diintegrasikan untuk membentuk\nkemampuan kepemimpinan, tanggung jawab, dan profesionalisme dalam praktik.</span></p><span style="font-size: 12px;">3. Struktur kurikulum Program Studi Diploma Tiga Keperawatan disusun berdasarkan prinsip </span><strong data-start="402" data-end="441"><span style="font-size: 12px;">Kurikulum OBE</span></strong><span style="font-size: 12px;">&nbsp;yang mengacu pada </span><strong data-start="460" data-end="518"><span style="font-size: 12px;">Kerangka Kualifikasi Nasional Indonesia (KKNI) level 5</span></strong><span style="font-size: 12px;"> dan </span><strong data-start="523" data-end="572"><span style="font-size: 12px;">Standar Nasional Pendidikan Tinggi (SN-Dikti)</span></strong><span style="font-size: 12px;">. Pemilihan struktur kurikulum dilakukan melalui proses analisis kebutuhan kompetensi lulusan, telaah regulasi nasional bidang kesehatan, serta masukan dari berbagai pemangku kepentingan (stakeholder) seperti rumah sakit, puskesmas, organisasi profesi (PPNI), dan alumni.</span></p><p><p><span style="font-family:&quot;Arial Narrow&quot;,sans-serif;mso-bidi-font-family:\n&quot;Times New Roman&quot;"><span style="font-size: 12px;">4.&nbsp;&nbsp;</span></span><span style="font-size: 12px;">Kurikulum dirancang berbasis </span><strong data-start="686" data-end="724"><span style="font-size: 12px;">capaian pembelajaran lulusan (CPL)</span></strong><span style="font-size: 12px;"> yang berorientasi pada </span><strong data-start="748" data-end="806"><span style="font-size: 12px;">Kerangka Kualifikasi Nasional Indonesia (KKNI) level 5</span></strong><span style="font-size: 12px;"> serta selaras dengan </span><strong data-start="828" data-end="877"><span style="font-size: 12px;">Standar Nasional Pendidikan Tinggi (SN-Dikti)</span></strong><span style="font-size: 12px;">. Setiap komponen kurikulum—mulai dari mata kuliah teori, laboratorium, hingga praktik klinik—dihubungkan secara langsung dengan visi dan misi program studi yang menekankan pada kualitas asuhan keperawatan, sikap profesional, serta penerapan nilai-nilai humanistik dan etika keperawatan. Struktur kurikulum mendukung </span><strong data-start="1195" data-end="1217"><span style="font-size: 12px;">visi program studi yaitu penyakit tidak menular</span></strong><span style="font-size: 12px;">&nbsp;melalui pendekatan sebagai edukator. Keterkaitan dengan </span><strong data-start="1679" data-end="1701"><span style="font-size: 12px;">misi program studi</span></strong><span style="font-size: 12px;"> tercermin dalam penguatan kegiatan akademik dan praktik klinik. Misi untuk menghasilkan lulusan yang kompeten dan beretika diimplementasikan melalui kurikulum berbasis kompetensi yang menekankan pembelajaran praktik (60% dari total SKS). Mahasiswa ditempatkan di lahan praktik seperti rumah sakit islam siti khadijah, RS Bhayangkara, RS Ernaldi Bahar, puskesmas yang ada di kota palembang,untuk mengembangkan keterampilan profesional dan kepedulian sosial. Kurikulum juga mendukung misi pendidikan dan pengabdian kepada masyarakat melalui kegiatan pada mata kuliah promosi kesehatan yang berorientasi pada peningkatan kesejahteraan masyarakat.</span><strong><span style="font-size: 12px;">&nbsp;selain itu&nbsp;</span></strong><strong data-start="2325" data-end="2351"><span style="font-size: 12px;">unggulan program studi</span></strong><span style="font-size: 12px;"> diwujudkan melalui integrasi mata kuliah dan kegiatan yang keperawatan penyakit tidak menular, sesuai dengan kebutuhan pelayanan kesehatan saat ini. Penguatan aspek keperawatan komunitas, promosi kesehatan, dan pendekatan keluarga menjadikan lulusan siap berperan dalam sistem pelayanan kesehatan primer yang menjadi prioritas nasional.</span></p></p><p><p><span style="font-family:&quot;Arial Narrow&quot;,sans-serif;mso-bidi-font-family:\n&quot;Times New Roman&quot;"><span style="mso-spacerun:yes">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span><br></span></p>\n\n<p><span lang="EN-ID" style="font-size:11.0pt;line-height:107%;font-family:&quot;Arial Narrow&quot;,sans-serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-bidi-font-family:\n&quot;Times New Roman&quot;;mso-ansi-language:EN-ID;mso-fareast-language:EN-US;\nmso-bidi-language:AR-SA"><span style="mso-spacerun:yes">&nbsp; &nbsp; &nbsp; &nbsp;</span><br></span></p>  </p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-04 03:11:32', '2025-11-04 05:27:45'),
	(26, 41, 92, '<p class="MsoListParagraphCxSpFirst" style="text-align:justify;text-indent:-.25in;\nmso-list:l0 level1 lfo1"><!--[if !supportLists]-->1.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><!--[endif]--><span dir="LTR"></span>Setiap mahasiswa baru di STIK Siti Khadijah berhak mendapatkan\npembimbing akademik yang membimbing mereka dari awal masuk hingga smenyelesaikan\nkewajibannya sebagai mahasiswa. Pembimbing akademik akan membimbing mereka pada\nhal yang bersifat akademik saja walaupun tidak menutup kemungkinan bimbingan\nnon akademik juga dapat dikonsultasikan. Adapun layanan bantuan keuangan di\nSTIK Siti Khadijah berupa program KIP Kuliah, beasiswa mahasiswa kurang mampu,\nbeasiswa mahasiswa berprestasi, dan minat bakat berada di ranah wakil 3 bidang\nkemahasiswaan melalui BAAK. <o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="text-align:justify;text-indent:-.25in;\nmso-list:l0 level1 lfo1"><!--[if !supportLists]-->2.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><!--[endif]--><span dir="LTR"></span>Layanan kademik dan non akademik direkomendasikan dan\ndikomunikasikan kepada staf dan mahasiswa masing-masing melalui BAAK dan BAUK.\nKomunikasi kepada staf dilakukan oleh wakil 2 melalui BAUK dan komunikasi\nkepada mahasiswa dilakukan oleh wakil 1 dan wakil 3 melalui BAAK.<o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="text-indent:-.25in;mso-list:l0 level1 lfo1"><!--[if !supportLists]-->3.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span>Manjemen STIK Siti Khadijah\nmelalui wakil 3 bidang kemahasiswaan memberikan keleluasaan kepada organisasi\nmahasiswa untuk Menyusun program kerja masing-masing ormawa. Dengan keleluasaan\npenyusunan program kerja, setiap ormawa dapat secara leluasa menuangkan rencana-rencana\nsesuai dengan kebutuhan dan kesesuaian organisasi masing-masing<o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="text-indent:-.25in;mso-list:l0 level1 lfo1"><!--[if !supportLists]-->4.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span><span style="font-size:\n11.0pt;line-height:115%">Manajemen memastikan bahwa kelayakan layanan\nkemahasiswaan telah memenuhi kebutuhan keberagaman mahasiswa melalui survey\nyang secara berkala dilakukan oleh Tim Penjamin mutu Internal. Sebagai tambahan,\nmahasiswa yang diwakili oleh organisasi mahasiswa maupun himpunan mahasiswa\njurusan berhak menyampaikan aspirasi mereka melalui ka sub bag kemahasiswaan\nyang selanjutnya dapat ditindaklanjuti ke tahap manajemen melalui ka. BAAK</span><o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="text-indent:-.25in;mso-list:l0 level1 lfo1"><!--[if !supportLists]-->5.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span><span style="font-size:\n11.0pt;line-height:115%">PS memiliki prosedur untuk mengevaluasi efektivitas\nlayanan akademik dan non akademik dilakukan melalui berbagai metode misalnya\nsurvei dan pengaduan melalui dosen pembimbing akademik sehingga dapat mengakomodasi\nperubahan yang terjadi. </span><o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpLast" style="text-indent:-.25in;mso-list:l0 level1 lfo1"><!--[if !supportLists]-->6.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span>Manajemen melalui wakil\nketua 3 bidang kemahasiswaan membuka peluang seluas-luasnya bagi mahasiswa yang\nmengusulkan untuk mengikuti kegiatan akademik maupun non-akademik yang bersifat\nkompetitif baik local, regional, maupun nasional. Kegiatan tersebut diusulkan\nke pimpinan melalui sub bag kemahasiswaan<o:p></o:p></p> ', '<p></p><p>Untuk Mengetahui Ketercapaian Standar Mutu Kemahasiswaan</p>', '<p><p></p>1.&nbsp; &nbsp; Apakah UPPS/PS memiliki kebijakan tertulis tentang penyediaan layanan akademik dan non-akademik bagi mahasiswa? (Dokumen kebijakan layanan mahasiswa, pedoman akademik, buku panduan mahasiswa)<br>2.&nbsp; &nbsp; Apakah tersedia layanan penasihat akademik dan karir bagi mahasiswa, dan apakah pembimbingan dilakukan secara rutin? (dokumentasi konsultasi karir)<br>3.&nbsp; &nbsp; Apakah mahasiswa dilindungi oleh asuransi kesehatan dan/atau asuransi kecelakaan selama masa studi?<br>4.&nbsp; &nbsp; Apakah tersedia akses layanan kesehatan di kampus atau kerja sama dengan fasilitas kesehatan di sekitar kampus? (MOU dengan klinik/puskesmas/RS, laporan kegiatan pemeriksaan kesehatan, data penggunaan layanan)</p><p>1.&nbsp; &nbsp; Apakah informasi layanan akademik dan non-akademik dikomunikasikan secara sistematis dalam kegiatan orientasi mahasiswa baru?(DOK. Jadwal kegiatan orientasi, materi sosialisasi, dokumentasi kegiatan)<br>2.&nbsp; &nbsp; Apakah tersedia pusat informasi atau unit layanan mahasiswa yang menjadi rujukan untuk bertanya atau konsultasi terkait layanan?</p><p>1.&nbsp; &nbsp; Apakah tersedia layanan pengembangan minat dan bakat (organisasi, lomba, olahraga, seni, pelatihan soft skills)? (Dokumen kegiatan kemahasiswaan, laporan kegiatan UKM, data keikutsertaan mahasiswa)<br>2.&nbsp; &nbsp; &nbsp;Apakah organisasi kemahasiswaan dilibatkan dalam perencanaan program layanan akademik dan non-akademik?, Apakah organisasi kemahasiswaan berperan aktif dalam mengembangkan ide, inovasi, atau kegiatan layanan mahasiswa (akademik maupun non-akademik)? (Dok. Proposal kegiatan, laporan program kerja, dokumentasi kegiatan)<br>3.&nbsp; &nbsp; Apakah layanan akademik dan non-akademik dijalankan melalui kegiatan bersama antara program studi dan organisasi kemahasiswaan?, Apakah terdapat mekanisme formal untuk koordinasi antara pimpinan program studi dan organisasi kemahasiswaan?<br>4.&nbsp; &nbsp; &nbsp;Apakah kegiatan organisasi kemahasiswaan selaras dengan layanan akademik (pengembangan karakter, soft skills, kepemimpinan)?, Apakah dilakukan evaluasi terhadap efektivitas kolaborasi UPPS/PS dengan organisasi kemahasiswaan dalam mendukung layanan mahasiswa? (PROKER BEM, HASIL KEGIATAN, HASIL EVALUASI, RTL)<br>5.&nbsp; &nbsp; Apakah dilakukan evaluasi rutin terhadap efektivitas dan kepuasan mahasiswa terhadap layanan akademik dan non-akademik? (dok. survei kepuasan), dan RTL?</p><p>1.&nbsp; &nbsp; Apakah UPPS/PS memiliki kebijakan atau prosedur untuk menilai kelayakan layanan mahasiswa dari aspek SDM, keuangan, dan sarana prasarana?, Apakah tenaga pendukung layanan (dosen pembimbing, konselor, tenaga kependidikan) memiliki kompetensi dan kualifikasi sesuai kebutuhan layanan?, Apakah jumlah SDM yang terlibat dalam layanan memadai dibandingkan dengan jumlah mahasiswa penerima layanan?<br>2.&nbsp; &nbsp; Apakah tersedia alokasi anggaran yang memadai dan berkelanjutan untuk mendukung layanan akademik dan non-akademik mahasiswa?, Apakah penggunaan dana untuk layanan mahasiswa dikelola secara efektif dan transparan? (lpj kegiatan keuangan)<br>3.&nbsp; &nbsp; &nbsp;Apakah dilakukan pemeliharaan rutin dan pembaruan sarana-prasarana layanan mahasiswa secara berkala?</p><p>1.&nbsp; &nbsp; Apakah layanan dimonitoring dan dievaluasi secara berkala bersama perwakilan mahasiswa untuk memastikan relevansi, aksesibilitas, dan kerahasiaan?</p><p>1.&nbsp; &nbsp; Apakah terdapat kebijakan tertulis tentang dukungan terhadap pengembangan prestasi akademik dan non-akademik mahasiswa?(Dokumen kebijakan kemahasiswaan, pedoman prestasi, SK dukungan kegiatan mahasiswa)<br>2.&nbsp; &nbsp; Apakah&nbsp; memiliki program yang dirancang untuk meningkatkan prestasi akademik mahasiswa (bimbingan belajar, pelatihan, lomba ilmiah, seminar)? (Jadwal kegiatan akademik, dokumentasi kegiatan ilmiah, laporan kegiatan mahasiswa)<br>3.&nbsp; &nbsp; Apakah terdapat kegiatan yang mendorong prestasi non-akademik (olahraga, seni, organisasi, kompetisi nasional/internasional)? (Laporan kegiatan UKM, dokumentasi lomba, penghargaan non-akademik) (dok, lomba)<br>4.&nbsp; &nbsp; Apakah tersedia fasilitas dan sumber daya (ruang latihan, dana kegiatan, pembimbing) untuk mendukung prestasi mahasiswa?<br>5.&nbsp; &nbsp; Apakah mahasiswa berprestasi mendapat dukungan berupa beasiswa, bantuan dana, atau insentif lainnya dari institusi atau mitra eksternal? (lpj)<br>6.&nbsp; &nbsp; Apakah menyediakan pembimbing akademik, dosen pendamping lomba, atau mentor bagi mahasiswa berprestasi?, monev kegiatan dan RTL<br><br><br><br><br><br></p>', NULL, NULL, NULL, NULL, NULL, '2025-11-04 06:40:03', '2025-11-29 05:15:28'),
	(27, 41, 94, '<p class="MsoListParagraphCxSpFirst" style="margin-left:1.0in;mso-add-space:auto;\ntext-indent:-.25in;mso-list:l0 level2 lfo1"><!--[if !supportLists]-->1.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span>Ada terdapat pada pedoman\npenerimaan mahasiswa baru<o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="margin-left:1.0in;mso-add-space:\nauto;text-indent:-.25in;mso-list:l0 level2 lfo1"><!--[if !supportLists]-->2.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span><!--[endif]--><span dir="LTR"></span>Ada terdapat pada pedoman\nlayanan lemahasiswaan<o:p></o:p></p>\n\n<p class="MsoListParagraphCxSpMiddle" style="margin-left:1.0in;mso-add-space:\nauto;text-indent:-.25in;mso-list:l0 level2 lfo1"><!--[if !supportLists]-->3.<span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;">&nbsp;&nbsp;&nbs