INSERT INTO `mutu_detailform` (`dtform_id`, `dtform_tujuan`, `dtform_pertanyaan`, `dtform_lingkup`, `dtform_update`, `dtform_create`, `form_id`) VALUES
	(2, '', '<p><strong>&nbsp;Kriteria 1 Visi, Misi, Tujuan dan Strategis</strong></p>\r\n<p>&nbsp;</p>', '<p>Bagaimana rumusan visi misi, dan unggulan program studi (PS) diploma tiga Keperawatan ditetapkan ?</p>\r\n<p>Dokumen Pendukung :</p>\r\n<ul>\r\n<li>Laporan kegiatan atau notulen rapat perumusan visi, misi, dan unggulan program studi.&nbsp;</li>\r\n<li>Dokumen rencana strategi (renstra) dan rencana operasional (renop)&nbsp;</li>\r\n</ul>\r\n<p>&nbsp;</p>', '2025-10-18 08:28:57', '2025-10-18 01:45:36', 4),
	(6, '', '<p>2.1 Capaian Pembelajaran Dalam Kurikulum</p>\r\n<p>Program studi (PS) telah menetapkan capaian pembelajaran lulusan, serta capaian pembelajaran yang&nbsp;<br>diharapkan untuk setiap mata kuliah.&nbsp;</p>', '<ol>\r\n<li>Bagaimana PS bertanggung jawab untuk menenentukan isi kurikulum?</li>\r\n<li>bagaimana isi kurikulum ditentukan?</li>\r\n<li>elemen-elemen apa saja dari ilmu biomedis dasar yang dimasukkan dalam kurikulum? bagaimana kedalamn dan keluasan dari pilihan yang dibuat serta waktu yang dialokasikan untuk elemen-elemen ini?</li>\r\n<li>elemen-elemen ilmu keterampilan keperawatan dasar serta keperawatan klinik apa saja yang tercakup dalam kurikulum? bagaimana menentukan alokasi waktu dan menilai kredit dari elemen-elemen tersebut?</li>\r\n<li>elemen-elemen apa saja dari ilmu perilaku, etik dan legal keperawayan serta sosial humaniora yang relevan dengan konteks dan budaya lokal yang dimasukkan dalam kurikulum? bagaimana pilihan dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>bagaimana mahasiswa mengenal bidang-bidang tertentu yang tidak banyak dibahas atau tidak tercakup dalam kurikulum?</li>\r\n<li>bagaimana PS memodifikasi isi kurikulum yang berkaitan dengan kemajuan dan perkembangan ilmu pengetahuan dan teknologi?</li>\r\n<li>bagaiaman prinsip metode ilmiah dan penelitian kesehatan keperawatan dibahas dalam kurikulum?</li>\r\n<li>bagaimana elemen-elemen dari ilmu sistem kesehatan termasuk sistem pelayanan kesehatan yang dimasukkan ke dalam kurikulum ?</li>\r\n<li>begaimana elemen dari ilmu seni mencakup filsafat, sejarah, seni, dan spiritualitas yang dimasukkan ke dalam kurikulum? bagaimana pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut ?</li>\r\n</ol>', '2025-10-18 05:28:11', '2025-10-18 05:26:15', 5),
	(7, '', '<p>2.2 Struktur Kurikulum</p>\r\n<p>Program studi (PS) memiliki dokumen lengkap mengenai struktur kurikulum yang meliputi prinsip&nbsp;<br>yang mendasari model kurikulum yang dipilih dan hubungan antar disiplin ilmu, mengikuti kemajuan&nbsp;<br>ilmu dan teknologi serta memenuhi kebutuhan masyarakat.&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify; text-justify: inter-ideograph;">&nbsp;</p>', '<ol>\r\n<li>Bagaimana penerapan prinsip pengembangan struktur kurikulum program studi diploma tiga Keperawatan?</li>\r\n<li>bagaimana keterkaitan berbagai disiplin ilmu yang tercakup dalam kurikulum diploma tiga Keperawatan ?</li>\r\n<li>bagaiaman struktur kurikulum dipilih? sejauh mana model tersebut selaras dengan regulasi nasional?</li>\r\n<li>bagaimana struktur kurikulum mendukung visi, misi dan unggulan program studi diploma tiga Keperawatan?</li>\r\n</ol>', '2025-10-18 05:28:34', '2025-10-18 05:26:52', 5),
	(8, '', '<p><strong>2.3 Isi Kurikulum</strong></p>\r\n<ul>\r\n<li><strong>Program studi (PS) menggunakan bahan kajian yang diperlukan untuk mempersiapkan&nbsp;<br>mahasiswa sebagai perawat ahli maya yang kompeten dan untuk pendidikan tahap&nbsp;<br>selanjutnya. &nbsp;</strong></li>\r\n<li><strong>Isi kurikulum setidaknya memuat bidang utama: ilmu biomedis dasar, ilmu dan&nbsp;<br>keterampilan keperawatan dasar dan klinis, serta ilmu perilaku dan sosial humaniora yang&nbsp;<br>relevan berdasarkan etik dan legal keperawatan. &nbsp;</strong></li>\r\n</ul>', '<ol>\r\n<li>Bagaimana PS bertanggung jawab untuk menenentukan isi kurikulum?</li>\r\n<li>bagaimana isi kurikulum ditentukan?</li>\r\n<li>elemen-elemen apa saja dari ilmu biomedis dasar yang dimasukkan dalam kurikulum? bagaimana kedalamn dan keluasan dari pilihan yang dibuat serta waktu yang dialokasikan untuk elemen-elemen ini?</li>\r\n<li>elemen-elemen ilmu keterampilan keperawatan dasar serta keperawatan klinik apa saja yang tercakup dalam kurikulum? bagaimana menentukan alokasi waktu dan menilai kredit dari elemen-elemen tersebut?</li>\r\n<li>elemen-elemen apa saja dari ilmu perilaku, etik dan legal keperawayan serta sosial humaniora yang relevan dengan konteks dan budaya lokal yang dimasukkan dalam kurikulum? bagaimana pilihan dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>bagaimana mahasiswa mengenal bidang-bidang tertentu yang tidak banyak dibahas atau tidak tercakup dalam kurikulum?</li>\r\n<li>bagaimana PS memodifikasi isi kurikulum yang berkaitan dengan kemajuan dan perkembangan ilmu pengetahuan dan teknologi?</li>\r\n<li>bagaiaman prinsip metode ilmiah dan penelitian kesehatan keperawatan dibahas dalam kurikulum?</li>\r\n<li>bagaimana elemen-elemen dari ilmu sistem kesehatan termasuk sistem pelayanan kesehatan yang dimasukkan ke dalam kurikulum ?</li>\r\n<li>begaimana elemen dari ilmu seni mencakup filsafat, sejarah, seni, dan spiritualitas yang dimasukkan ke dalam kurikulum? bagaimana pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut ?</li>\r\n</ol>', '2025-10-18 05:29:23', '2025-10-18 05:27:28', 5),
	(9, '', '<p>3.1 Kebijakan dan Sistem Penilaian</p>\r\n<p class="MsoNormal" style="text-align: justify; text-justify: inter-ideograph;">Kebijakan penilaian dengan sistem terpusat yang memandu dan mendukung implementasinya, menggunakan berbagai metode formatif dan sumatif yang mengukur pencapaian kompetensi lulusan dalam pengetahuan, keterampilan klinis, dan sikap yang diperlukan untuk menjadi seorang Perawat Ahli Madya Keperawatan menekankan kepatuhan terhadap standar operasional prosedur [SOP], sikap dan kompetensi ahli madya keperawatan, menjaga keselamatan pasien, mahasiswa dan lingkungan. Kebijakan dan sistem harus mengoperasionalkan pelaksanaan pencapaian visi dan misi Institusi dan PS, metode pembelajaran untuk pencapaian capaian pembelajaran lulusan sebagai perawat ahli madya keperawatan dengan sumber daya yang tersedia.</p>', '<ol>\r\n<li>Bagaimana penilaian capaian pembelajaran lulusan yang digunakan oleh PS diploma tiga Keperawatan?</li>\r\n<li>bagaimana keputusan dibuat mengenai transparansi penilaian dan waktunya?</li>\r\n<li>bagaimana penilaian diintegrasikan dan dikooedinasikan pada berbagai capaian pembelajaran dan kurikulum?</li>\r\n</ol>', '2025-10-18 05:35:23', '2025-10-18 05:35:23', 6),
	(10, '', '<p>3.2 Penilaian dalam Mendukung Pembelajaran</p>\r\n<p class="MsoNormal" style="text-align: justify; text-justify: inter-ideograph;">PS mempunyai sistem penilaian yang secara teratur memberikan umpan balik yang dapat ditindaklanjuti oleh mahasiswa, mengidentifikasi kekuatan dan kelemahan mereka, serta membantu mengkonsolidasikan pembelajarannya. Penilaian formatif yang mengukur pengetahuan, keterampilan dan sikap yang menekankan kepatuhan terhadap standar operasional prosedur [SOP], sikap dan kompetensi ahli madya keperawatan, menjaga keselamatan pasien, mahasiswa dan lingkungan dirancang sebagai bagian dari intervensi edukatif untuk memastikan bahwa semua mahasiswa mempunyai kesempatan untuk mencapai potensi maksimal mereka dalam capaian pembelajaran. Umpan balik merupakan salah satu pendorong terbesar dalam pencapaian pembelajaran. Mahasiswa perlu dinilai sejak dini dan secara teratur dalam mata kuliah dan penempatan klinis untuk memberikan umpan balik yang memandu pembelajaran mereka. Hal ini mencakup identifikasi awal mahasiswa yang berkinerja kurang baik dan tawaran remediasi.</p>', '<ol>\r\n<li>Bagaimana penilaian yang dilakukan kepada mahasiswa PS diploma tiga Keperawatan dalam mencapai capaian pembelajaran?</li>\r\n<li>bagaimana cara mengindentifikasi mahasiswa dari hasil penilaian yang membutuhkan bantuan tambahan?</li>\r\n<li>bagaimana mahasiswa mendapatkan supervisi dan pengarahan oleh pembimbing klinik dalam mencapai capaian pembelajaran klinik ?</li>\r\n<li>sistem dukungan apa yang dapat ditawarkan kepada mahasiwsa yang teridentifikasi memiliki kebutuhan tambahan?</li>\r\n</ol>', '2025-10-18 05:38:38', '2025-10-18 05:38:24', 6),
	(11, '', '<p>3.3 Penilaian untuk mendukung pengambilan keputusan</p>\r\n<p class="MsoNormal" style="text-align: justify; text-justify: inter-ideograph;">Unit Pengelola Program Studi (UPPS) dan Program Studi (PS) mempunyai sistem penilaian yang menginformasikan keputusan mengenai kemajuan dan kelulusan mahasiswa. Penilaian sumatif yang menekankan kepatuhan terhadap standar operasional prosedur [SOP], sikap dan kompetensi ahli madya keperawatan, menjaga keselamatan pasien, mahasiswa dan lingkungan dilakukan untuk mengukur capaian pembelajaran. Penilaian dirancang dengan baik, menghasilkan skor/nilai yang valid. Penilaian dalam pengambilan keputusan sangat penting untuk akuntabilitas kelembagaan. Penilaian ini harus adil bagi mahasiswa secara individu maupun kelompok, dan harus dapat membuktikan seluruh pencapaian kompetensi.</p>', '<ol>\r\n<li>Bagaiaman <em>blueprint&nbsp;</em>(cetak biru) dikembangkan untuk ujian?</li>\r\n<li>Bagaimana standar (nilai kelulusan) ditetapkan pada ujian sumatif?</li>\r\n<li>bagaimana mekanisme banding mengenai hasil penilaian yang tersedia bagi mahasiswa?</li>\r\n<li>Bagaimana cara memberikan informasi kepada mahasiswa dan pemangku kepentingan lainya, mengenai isi, metode, dan kualitas penilaian?</li>\r\n<li>bagaimana penilaian digunakan sebagai pedoman untuk menentukan perkembangan pembelajaran mahasiswa?</li>\r\n</ol>', '2025-10-18 05:49:44', '2025-10-18 05:49:44', 6),
	(12, '', '<p>Lingkungan Kerja dan Belajar Mahasiswa</p>', '<ol>\r\n<li>bagaimana UPPS memastikan bahswa lingkungan kerja dan belajar mahasiswa memenuhi standar mutu dan keselamatan mahasiswa?</li>\r\n<li>Bagaimana PS menghitung dan menentukan beban dan jam belajar praktek klinis?</li>\r\n<li>Bagaimana PS menerapkan rencana kerja kegiatan mahasiswa, penyediaan layanan, pendidikan, dan program keselamatan kepada mahasiswa ditetapkan, disosialisasikan, dan dilaksanakan?</li>\r\n<li>Bagaimana UPPS/PS menentapkan jumlah jam belajar minimum dan maksimum yang diperlukan, serta pengaturan hari libur bagi mahasiswa diploma tiga Keperawatan?</li>\r\n<li>Bagaimana UPPS/PS mengatur pelaksanaan beban kerja dan tanggung jawab praktik profesi bagi mahasiswa diploma tiga Keperawatan?</li>\r\n<li>Bagaimanan UPPS/PS menagtur untuk perisapan dan pelaksanaan ujian dengan tetap menjaga keamanan mahasiswa?</li>\r\n</ol>', '2025-10-18 06:12:23', '2025-10-18 06:12:23', 7),
	(13, '', '<p>Kebijakan Penetapan Dosen</p>', '<ol>\r\n<li>Bagaiaman program studi menentukan jumlah dan kualifikasi dosen yang dibutuhkan ?</li>\r\n<li>Bagaimana menetapkan jumlah dan kualifikasi dosen agar selaras dengan rancangan, penerapan, dan penjaminan mutu kurikulum?</li>\r\n</ol>', '2025-10-18 06:24:19', '2025-10-18 06:24:19', 9),
	(14, '', '<p>Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol>\r\n<li>Bagaimana program studi menjamin relevansi penelitian dosen dalam mendukung pencapaian visi misi dan unggulan program studi serta monitoring, evaluasi, dan tindak lanjutnya?</li>\r\n<li>Bagaimana program studi mengimplementasikan kegiatan penelitian dosen di UPPS?</li>\r\n<li>Bagaimana integrasi hasil penelitian dalam kegiatan pemebelajaran?</li>\r\n</ol>', '2025-10-18 06:27:10', '2025-10-18 06:27:10', 9),
	(15, '', '<p>Relevansi Pengabdian kepada Masyarakat sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol>\r\n<li>Bagaimana upaya Program Studi menjamin relevansi Pengabdian Kepada Masyarakat (PkM) dosen dalam mendukung pencapaian visi misi dan keunggulan Program studi serta monitoring, evaluasi dan tindak lanjutnya?</li>\r\n<li>Bagaimana program studi mengimplementasikan kegiatan pengabdian kepada masyarakat (PkM) di UPPS?</li>\r\n<li>Bagaimana integrasi hasil PkM dalam kegiatan pembelajaran?</li>\r\n</ol>', '2025-10-18 06:30:09', '2025-10-18 06:30:09', 9),
	(16, '', '<p>Sumber daya keterampilan klinis</p>', '<ol>\r\n<li>Bagaimana program studi merumuskan kebijakan untuk pelaksanaan metode pembelajaran praktikum dengan simulasi menggunakan pasien sebenarnya?</li>\r\n<li>Bagaimana program studi memastikan sumberdaya pembelajaran praktik klinik dilaksanakan secara konsisten sesuai kurikulum?</li>\r\n<li>Bagaimana program studi menyelenggarakan program pembelajaran praktikum bagi mahasiswa diploma tiga keperawatan baik praktikum laboratorium dan praktik klinik keperawatan di layanan kesehatan klinik dan komunitas yang mendukung capaian pembelajaran lulusan?</li>\r\n<li>Bagaimana program studi memasitikan bahwa mahasiswa memiliki akses yang memadai terhadao fasilitas klinis?</li>\r\n<li>Bagaimana program studi mengatru penempatan mahasiswa dalam praktik klinik sesuai capaian pembelajaran?</li>\r\n<li>Bagaimana program studi melibatkan dosen dan pembimbing klinik dalam rangkaian praktik klinik sesuai capaian pembelajaran lulusan?</li>\r\n</ol>', '2025-10-18 06:39:57', '2025-10-18 06:39:57', 10),
	(17, '', '<p><strong>Kriteria 1 Visi, Misi, Tujuan dan Strategis</strong></p>\r\n<p class="MsoNormal">&nbsp;</p>', '<p>Bagaimana mekanisme penyusunan visi, misi, dan unggulan program studi diploma Tiga Keperawatan dan diturunkan ke dalam rencana strategis dan operasional di PS?</p>\r\n<p>Dokumen pendukung :</p>\r\n<p>Bukti kegiatan keterlibatan pemangku kepentingan internal (mahasiswa, dosen, tendik, pengelola)&nbsp; dan eksternal (lulusan, pengguna lulusan, mitra, pakar, organisasi profesi dan pemerintah) seperti&nbsp; rekaman foto/video pada saat pertemuan.&nbsp;</p>', '2025-10-18 08:24:34', '2025-10-18 08:14:27', 4),
	(19, '', '<p><strong>Kriteria 1 Visi, Misi, Tujuan dan Strategis</strong></p>\r\n<p class="MsoNormal">&nbsp;</p>', '<p>Bagaimana visi, misi dan keunggulan menentukan peran program studi diploma tiga Keperawatan di dalam masyarakat?</p>', '2025-10-18 08:15:41', '2025-10-18 08:15:17', 4),
	(20, '', '<p><strong>Kriteria 1. Visi, Misi, Tujuan, dan Strategi &nbsp;</strong></p>', '<p>Bagaimana visi, misi, dan unggulan&nbsp; diterjemahkan kedalam perencanaan,&nbsp; implementasi, monitoring, evaluasi dan&nbsp; tindaklanjutnya untuk perbaikan UPPS&nbsp; dan PS diploma tiga Keperawatan?</p>', '2025-10-18 08:21:54', '2025-10-18 08:17:01', 4),
	(21, '', '<p><strong>Kriteria 1. Visi, Misi, Tujuan, dan Strategi &nbsp;</strong></p>', '<p>Bagaimana kesesuaian visi, misi, dan&nbsp; unggulan dengan standar dan peraturan&nbsp; nasional tentang pendidikan tinggi&nbsp; bidang kesehatan?&nbsp;</p>', '2025-10-18 08:21:48', '2025-10-18 08:17:19', 4),
	(22, '', '<p><strong>Kriteria 1. Visi, Misi, Tujuan, dan Strategi &nbsp;</strong></p>', '<p>Bagaimana cara menyosialisasikan visi,&nbsp; misi, dan unggulan program studi,&nbsp; analisis hasil dan tindaklanjutnya?</p>\r\n<p>Dokumen pendukung:</p>\r\n<p>Media yang digunakan untuk publikasi visi, misi, dan unggulan dan laporan sosialisasi.&nbsp;</p>', '2025-10-18 08:27:46', '2025-10-18 08:17:37', 4),
	(23, '', '<p>PS menyatakan secara terbuka mengenai visi, misi, tujuan, strategi, nilai-nilai, dan unggulan&nbsp; (visi keilmuan).&nbsp;<br>Jelaskan secara singkat dan ringkas tujuan dari PS Diploma Tiga Kebidanan, nilai-nilai, tujuan&nbsp; pendidikan, peranan penelitian, dan kaitannya dengan layanan kebidanan. Tunjukkan sejauh mana&nbsp; pernyataan tersebut telah disusun dengan melibatkan para pemangku kepentingan. Jelaskan bagaimana pernyataan misi mendasari penyusunan kurikulum dan penjaminan mutu.&nbsp;</p>', '<p>Bagaimana rumusan visi, misi, dan tujuan unggulan PS Diploma Tiga Kebidanan ditetapkan ?</p>\r\n<p>Dokumen pendukung :</p>\r\n<ul>\r\n<li>Notulen rapat pada saat perumusan visi, misi, dan unggulan PS yang berasal dari visi dan misi UPPS</li>\r\n<li>Laporan keterlibatan pemangku kepentingan&nbsp;</li>\r\n<li>media yang digunakan untuk publikasi visi, misi dan unggulan</li>\r\n<li>Renstra dan Renop</li>\r\n<li>dokumen standara pendidikan</li>\r\n</ul>', '2025-10-21 03:12:30', '2025-10-20 06:37:40', 11),
	(24, '', '<p>Kriteri 1 Visi, Misi, Tujuan dan Strategis</p>', '<ol>\r\n<li>Bagaimana rumusan visi, misi, dan unggulan PS Diploma Tiga Kebidanan ditetapkan?</li>\r\n<li>Bagaimana visi, misi, dan unggulan disesuaikan dengan rencana strategis, penjaminan mutu, dan manajemen di PS Diploma Tiga Kebidanan?</li>\r\n<li>Bagaimana pemangku kepentingan &nbsp;terlibat dalam penyusunan visi, misi, dan unggulan PS Diploma Tiga Kebidanan?</li>\r\n<li>Bagaimana visi, misi, dan unggulan menentukan peran PS Diploma Tiga Kebidanan di dalam masyarakat?&nbsp;</li>\r\n<li>Bagaimana kesesuaian visi, misi, dan unggulan dengan filosofi dan pelaksanaan program, serta standar badan akreditasi dan &nbsp;peraturan nasional tentang pendidikan tinggi bidang kesehatan?</li>\r\n<li>Bagaimana cara menyosialisasikan visi, misi, dan unggulan PS Diploma Tiga Kebidanan, analisis hasil dan tindaklanjutnya?</li>\r\n</ol>', '2025-10-20 06:56:40', '2025-10-20 06:48:15', 12),
	(25, '', '<p>Kriteri 2 Kurikulum</p>\r\n<p>a) PS Diploma Tiga Kebidanan dapat memasukkan bahan kajian yang diperlukan untuk mempersiapkan mahasiswa menjadi bidan ahli madya yang kompeten dan untuk pendidikan tahap selanjutnya. &nbsp;<br>b) Isi kurikulum setidaknya memuat enam bidang utama: Ilmu kesehatan dasar dan keterampilan praktik bidan, etika hukum dan profesionalisme, manajemen, kesehatan masyarakat, ilmu sosial dan perilaku, dan metodologi penelitian dan bukti ilmiah.&nbsp;</p>', '<p>2.1 Capaian Pembelajaran dalm Kurikulum&nbsp;</p>\r\n<ol>\r\n<li>Bagaimana cara merancang dan mengembangkan&nbsp;<br>capaian pembelajaran secara umum dan spesifik?&nbsp;</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana capaian pembelajaran disesuaikan dengan kriteria kompetensi yang ditetapkan dan peraturan yang berlaku</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Pendekatan apa yang digunakan dalam penyusunan kurikulum dan bagaimana kesesuaiannya terhadap visi, misi, dan unggulan</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana keterlibatan pemangku kepentingan dalam pengembangan kurikulum?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana PS Diploma Tiga Kebidanan menyediakan pengalaman belajar yang diperlukan mahasiswa untuk mencapai tujuan pembelajaran?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana hubungan capaian pembelajaran lulusan dengan karier lulusan di masyarakat (tracer study)?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana memastikan capaian pembelajaran yang dipilih sesuai dengan lingkup sosial dari wilayah PS Diploma Tiga Kebidanan</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">Bagaimana PS Diploma Tiga Kebidanan menggunakan hasil evaluasi capaian pembelajaran mahasiswa sebagai dasar untuk mengevaluasi dan merencanakan pengembangan kurikulum selanjutnya?</p>\r\n</li>\r\n</ol>\r\n<p>2.2 Sturktur Kurikulum</p>\r\n<ol>\r\n<li>Apa saja prinsip yang melatarbelakangi desain kurikulum PS Diploma Tiga Kebidanan</li>\r\n<li>Bagaiaman keterkaitan berbagai disiplin ilmu yang tercakup dalam kurikulum?</li>\r\n<li>bagaimana struktur kurikulum dipilih? sejauh mana model tersebur dibatasi oleh regulasi nasional?</li>\r\n</ol>\r\n<p>2.3 Isi Kurikulum</p>\r\n<ol>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan bertanggung jawab untuk menentukan isi kurikulum?</li>\r\n<li>Bagaimanan isi kurikulum ditentukan?</li>\r\n<li>Bagaimana elemen dari ilmu kesehatan dasar dan keterampilan praktik bidan dimasukkan ke dalam kurikulum? bagaimana pilihan-pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut?</li>\r\n<li>bagaimanan elemen-elemen dari etika hukum dan profesionelism dimasukkan ke dalam kurikulum? bagaimana pilihan-pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut?</li>\r\n<li>Bagaimana elemen dari manajemen dimasukkan ke dalam kurikulum? bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>Bagaimana elemen darimilmu kesehatan masyarakat dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>Bagaimana elemen dari ilmu sosial dan perilaku dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>Bagaimana elemen dari metodologi penelitian dan bukti ilmiah dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li>Keterampilan klinis kebidanan apa saja yang dibutuhkan oleh semua mahasiswa untuk mendapatkan pengelaman praktik?</li>\r\n<li>Bagaimana mahasiswa diajarkan untuk mengambil keputusan klinis yang sesuai dengan menggunakan bukti terbaik yang tersedia?</li>\r\n<li>Bagaimana Ps Diploma Tiga Kebidanan mengalokasikan waktu bagi mahasiswa dalam pengaturan praktik klinik yang berbeda?</li>\r\n<li>Bagaimana mahasiswa mengenal bidang-bidang tertentu yang tidak banyak dibahasa atau tidak tercakup dalam kurikulum?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan mengembangkan isi kurikulum sesuai dengan kemajuan dan perkembangan ilmu pengetahuan terkini?</li>\r\n<li>Bidang apa saja yang bersifat pilihan? bagaimana bidang pilihan ditentukan?</li>\r\n<li>Bagaimana menjamin pembekajaran mahasiswa dalam disiplin ilmu yang tidak memiliki pengalaman khusus?</li>\r\n</ol>\r\n<p>2.4 Metode dan pengalaman Pembelajaran</p>\r\n<ol>\r\n<li>Bagaimana prinsip yang mendasari pemilihan metode dan pengalaman pembelajaran yang digunakan dalam kurikulum ditetapkan?</li>\r\n<li>Bagaimana dasar pemilihan dan pendistribusian prinsip, metode, dan pengalaman pembelajaran di dalam kurikulum?</li>\r\n<li>Bagaimana penerapan metode dan pengalaman pembelajaran yang diberikan kepada mahasiswa sesuai dengan lingkup, sumber daya, dan kearifan lokal?</li>\r\n</ol>\r\n<p>2.5 Keselamatan Pasien</p>\r\n<ol>\r\n<li>Bagaimana UPPS/PS/Wahana Praktik mendefinisikan dan mengkomunikasikan isu dilema etik dan aspek medikolegal mahasiswa dan keselamatan pasien kepada pemangku kepentingan</li>\r\n<li>Bagaimana UPPS/PS/ Wahana Praktik menetapkan kelompok atau individu yang bertanggung jawab untuk&nbsp;<br>memantau isu dilema etik dan aspek medikolegal mahasiswa dan keselamatan pasien pada tingkat manajemen program, wahana praktik dan layanan kesehatan?</li>\r\n<li>Bagaimana risiko terhadap keselamatan pasien ditinjau, diidentifikasi, dicatat, dan dilaporkan secara berkala?&nbsp;</li>\r\n<li>Bagaimana risiko dimitigasi dan ditangani?</li>\r\n<li>Bagaimana UPPS/PS/ Wahana Praktik menyiapkan mahasiswa dalam melakukan dokumentasi tindakan untuk&nbsp;<br>menghindari masalah dilema etik dan aspek medikolegal mahasiswa dan memastikan keselamatan pasien serta&nbsp;<br>langkah-langkah yang diambil ketika risiko teridentifikasi?</li>\r\n<li>Bagaimana lembaga terkait diberitahu mengenai masalah dan risiko keselamatan pasien?</li>\r\n</ol>', '2025-10-20 07:45:33', '2025-10-20 06:49:42', 12),
	(26, '', '<p>Kriteria 3. Penialaian</p>\r\n<ul>\r\n<li>&nbsp;UPPS/PS memiliki kebijakan yang menjelaskan tentang penilaian. &nbsp;</li>\r\n<li>UPPS/PS mempunyai sistem terpusat untuk memastikan bahwa kebijakan tersebut diwujudkan&nbsp;<br>melalui berbagai metode penilaian yang terkoordinasi dan selaras dengan capaian pembelajaran. &nbsp;</li>\r\n<li>Kebijakan tersebut disosialisasikan kepada seluruh pemangku kepentingan</li>\r\n</ul>', '<p><strong>3.1 Kebijakan dan Sistem Penilaian</strong></p>\r\n<ol>\r\n<li>Bagaimana metode penialaian yang digunakan untuk setiap capaian pembelajaran sesuai dengan prinsip penilaian?</li>\r\n<li>Bagaimana keputusan dibuat mengenai jumlah penilaian dan waktunya?</li>\r\n<li>Bagaimana penilaian diintegrasikan pada berbagai capaian pembelajaran dan kurikulum?</li>\r\n</ol>\r\n<p><strong>3.2</strong>&nbsp; <strong>Penilaian dalam mendukung pembelajaran</strong></p>\r\n<ol>\r\n<li>Bagaimana mahasiswa dinilai untuk meningkatkan hasil pembelajaranya</li>\r\n<li>Bagaimana cara menilai mahasiswa yang membutuhkan bantuan proses tambahan</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menyediakan sistem pendukung bagi mahasiswa yang teridentifikasi memiliki kebutuhan tambahan?</li>\r\n</ol>\r\n<p><strong>3.3&nbsp;</strong>Penilaian untuk Mendukung Pengambilan keputusan</p>\r\n<ol>\r\n<li>Bagaimana cetak biru (blueprint) dikembangkan untuk ujian?</li>\r\n<li>Bagaimana standar (nilai kelulusan) ditetapkan pada ujian sumatif?</li>\r\n<li>Bagaimana mekanisme bdaning mengenai hasil penilaian yang tersedia bagi mahasiswa?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan memberikan informasi kepada mahasiswa dan pemangku kepentingan lainya, mengenai isi, metode, dan kuantitias penilaian?</li>\r\n<li>Bagaimana penilaian digunakan sebagai pedoman untuk menentukan perkembangan pembelajaran mahasiswa?</li>\r\n</ol>\r\n<p>Dokumen pendukung :</p>\r\n<ul>\r\n<li>Rubrik penilaian</li>\r\n<li>daftar nilai mahasiswa</li>\r\n<li>KHS dan atau transkrip</li>\r\n<li>Prosedur remedial</li>\r\n<li>Bank soal dan contoh ujian</li>\r\n</ul>\r\n<p>&nbsp;</p>', '2025-10-21 04:24:03', '2025-10-21 03:17:49', 13),
	(27, '', '<p><strong>Lingkungan Kerja dan Belajar Mahasiswa</strong></p>', '<ol>\r\n<li>Bagaimana UPPS/PS pendidikan memastikan bahwa wahana praktik memenuhi standar mutu dan keselamatan pasien?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menghitung dan menentukan beban dan jam kerja praktik klinis?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menerapkan rencana kerja kegiatan mahasiswa, penyediaan layanan, pendidikan, dan program keselamatan kepada mahasiswa diputuskan, disebarluaskan, dan ditegakkan?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menentapkan jumlah jam kerja minimum dan maksimum yang diperlukan, pengaturan hari libur?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan mengatur untuk persiapan dan pelaksanaan ujian dengan tetap menjaga keamanan mahasiswa dan pasien?</li>\r\n</ol>\r\n<p>Dokumen pendukung :</p>\r\n<ul>\r\n<li>Dokumen hasil survei kepuasan mahasiswa terhadap proses pendidikan</li>\r\n<li>Dokumen hasil survei kepuasan mahasiswa terhadap layanan manajemen</li>\r\n</ul>', '2025-10-21 04:32:38', '2025-10-21 04:32:38', 14),
	(28, '', '<p>Kriteria 5. Dosen, Tendik, Penelitian dan Pengabdian kepada Masyarakat</p>', '<p><strong>5.1 Kebijakan Penetapan Dosen</strong></p>\r\n<ol>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menentukan jumlah dan kualifikasi dosen yang dibutuhkan?</li>\r\n<li>Bagaiman menetapkan jumlah dan kualifikasi dosen agar selaras dengan rencana, penerapan, dan penjaminan mutu kurikulum?</li>\r\n<li>Bagaimana UPPS/PS memastikan dosen dan tendik terhindar dari perundungan?</li>\r\n</ol>\r\n<p>&nbsp;</p>', '2025-10-21 06:40:11', '2025-10-21 04:57:34', 15),
	(29, '', '<p>Kriteria 6. Dosen, Tendik, Penelitian dan Pengabdian kepada Masyarakat</p>', '<p><strong>5.2 Kinerja dan Perilaku Dosen</strong></p>\r\n<ol>\r\n<li>Bagaimana UPPS/PS menyampaikan informasi akademik dan regulasi kepada dosen baru dan lama?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menyediakan pelatihan orientasi untuk dosen?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan menyiapkan dosen dan pembimbing klinik untuk melasksanakan kurikulum yang telah disusun di wahana praktik?</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '2025-10-21 05:02:03', '2025-10-21 05:02:03', 15),
	(30, '', '<p>Kriteria 6. Dosen, Tendik, Penelitian dan Pengabdian kepada Masyarakat</p>', '<p class="MsoNormal"><strong>5.3 Pengembangan Profesional Berkelanjutan untuk Dosen</strong></p>\r\n<ol style="margin-top: 0in;" start="1" type="1">\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Informasi apa yang diberikan PS kepada dosen baru dan dosen lama tentang pengembangan profesional berkelanjutan?</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Bagaimana PS mengambil tanggung jawab administratif atas penerapan kebijakan pengembangan profesional berkelnajutan dosen?</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Jaminan finansial apa yang disediakan PS Diploma Tiga Kebidanan untuk mendukung dosen dalam pengembangan profesional berkelanjutan?</li>\r\n</ol>\r\n<p>&nbsp;</p>', '2025-10-21 06:39:04', '2025-10-21 06:39:04', 15),
	(31, '', '<p>Kriteria 6. Dosen, Tendik, Penelitian dan Pengabdian kepada Masyarakat</p>', '<p class="MsoNormal" style="margin-left: 0.5in; text-align: left;"><strong>5.5 Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi</strong></p>\r\n<ol style="margin-top: 0in;" start="1" type="1">\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Bagaimana PS Diploma Tiga Kebidanan menjamin relevansi penelitian dosen dalam mendukung pencapaian visi misi dan unggulan PS serta monitoring dan evaluasinya?</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Bagaimana PS Diploma Tiga Kebidanan mengimplementasikan kegiatan penelitian di UPPS?</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Bagaimana integrasi hasil penelitian dalam kegiatan pembelajaran?</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo1; tab-stops: list .5in;">Bagaimana penghargaan dan pengakuan terhadap hasil penelitian dosen?</li>\r\n</ol>', '2025-10-21 06:40:47', '2025-10-21 06:40:47', 15),
	(32, '', '<p>Kriteria 6. Dosen, Tendik, Penelitian dan Pengabdian kepada Masyarakat</p>', '<p class="MsoNormal" style="margin-left: .5in;">5.6 Relevansi PkM sesuai dengan Visi dan Unggulan Program Studi&nbsp;</p>\r\n<ol style="margin-top: 0in;" start="1" type="1">\r\n<li class="MsoNormal" style="mso-list: l1 level1 lfo1; tab-stops: list .5in;">Bagaimana upaya PS Diploma Tiga Kebidanan menjamin relevansi PkM dosen dalam mendukung pencapaian visi misi dan keunggulan PS serta monitoring dan evaluasinya?</li>\r\n<li class="MsoNormal" style="mso-list: l1 level1 lfo1; tab-stops: list .5in;">Bagaimana PS Diploma Tiga Kebidanan mengimplementasikan kegiatan pengabdian kepada masyarakat di UPPS?</li>\r\n<li class="MsoNormal" style="mso-list: l1 level1 lfo1; tab-stops: list .5in;">Bagaimana integrasi hasil PkM dalam kegiatan pembelajaran?</li>\r\n<li class="MsoNormal" style="mso-list: l1 level1 lfo1; tab-stops: list .5in;">Bagaimana penghargaan dan pengakuan terhadap hasil PkM dosen?</li>\r\n</ol>\r\n<p class="MsoNormal" style="margin-left: .5in;">Dokumen Pendukung :</p>\r\n<ul style="margin-top: 0in;" type="disc">\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo2; tab-stops: list .5in;">Rencana pengembangan SDM sesuai dengan kebutuhan masing-masing disiplin ilmu</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo2; tab-stops: list .5in;">Pemetaan displin kurikulum (kesesuaian bidang ilmu dengan maga kuliah yang diampu dan beban kerja)</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo2; tab-stops: list .5in;">Bukti penghargaan atau pengakuan atas hasil penelitian dosen dan PkM (termasuk menerima: Hibah penelitian, Hibah PkM, dan HKI)</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo2; tab-stops: list .5in;">Sertifikat pendidik/dosen, Sertifikat kompetensi, ijazah</li>\r\n<li class="MsoNormal" style="mso-list: l0 level1 lfo2; tab-stops: list .5in;">HKI atau surat pengakuan/penghargaan dari lembaga nasioanl/internasional</li>\r\n</ul>', '2025-10-21 06:41:16', '2025-10-21 06:41:16', 15),
	(33, '', '<p>Sumber daya Keterampilan Klinis</p>', '<ol>\r\n<li>Apa saja kesempatan yang diperlukan dan disediakan bagi mahasiswa untuk mempelajari keterampilan klinis?</li>\r\n<li>Bagaimana pemanfaatan skill lab (laboratorium keterampilan), pasien simulasi, dan pasien sebenarnya?</li>\r\n<li>Apa dasar kebijakan penggunaan pasien simulasi dan pasien sebenarnya?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan memastikan bahwa mahasiswa memiliki akses yang memadai terhadap fasilitas klinis?</li>\r\n<li>Apa yang mendasari penempatan mahasiswa di wahana praktik di PS Diploma Tiga Kebidanan?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan melibatkan dosen dan pembimbing klinis dalam rangkaian stase klinis yang dibutuhkan?</li>\r\n<li>Bagaimana PS Diploma Tiga Kebidanan memastikan penyampaian infromasi tentang kurikulum dalam lingkungan klinis secara konsisten?</li>\r\n</ol>\r\n<p>Dokumen Pendukung :</p>\r\n<ul>\r\n<li>Daftar wahana praktik</li>\r\n<li>Daftar pasien standar dan laporan pelatihanya</li>\r\n<li>Daftar pelatihan dan laporanya dari dosen klinis ke pembimbing</li>\r\n<li>Laporan survei kepuasan atas pelayanan yang diberikan manajemen kepada seluruh pemangku kepentingan (mahasiswa, dosen, pegawai, rekanan, dan pengguna lulusan)</li>\r\n</ul>', '2025-10-21 06:49:49', '2025-10-21 06:49:49', 16),
	(34, '', '<p><strong>Kriteria 1. Pernyataan Visi, Misi, Tujuan, dan Strategis</strong></p>', '<ol>\r\n<li class="MsoNormal">Bagaimana rumusan visi, misi, dan unggulan Program Studi (PS) pendidikan profesi Ners ditetapkan?</li>\r\n<li class="MsoNormal">Bagaimana mekanisme penyusunan visi, misi, dan unggulan program studi pendidikan profesi Ners dan diturunkan kedalam rencana strategis dan operasional di PS?</li>\r\n<li class="MsoNormal">Bagaimana visi, misi, dan keunggulan menentukan peran program studi pendidikan profesi Ners di dalam masyarakat?</li>\r\n<li class="MsoNormal">Bagaimana visi, misi, dan unggulan diterjemahkan kedalam perencanaan, implementasi, monitoring, evaluasi dan tindaklanjutnya untuk perbaikan UPPS dan PS pendidikan profesi Ners?</li>\r\n<li class="MsoNormal">Bagaimana kesesuaian visi, misi, dan unggulan dengan standar dan peraturan nasional tentang pendidikan tinggi bidang kesehatan?</li>\r\n<li class="MsoNormal">Bagaimana cara menyosialisasikan visi, misi, dan unggulan program studi, analisis hasil dan tindaklanjutnya?</li>\r\n</ol>\r\n<p>Dokumen pendukung:</p>\r\n<ul>\r\n<li class="MsoNormal">Laporan kegiatan atau notulen rapat perumusan visi, misi, dan unggulan program studi. Bukti kegiatan keterlibatan pemangku kepentingan internal (mahasiswa, dosen,tendik, pengelola) dan eksternal (lulusan, pengguna lulusan, mitra, pakar, organisasi profesi dan pemerintah) seperti rekaman foto/video pada saat pertemuan.</li>\r\n<li class="MsoNormal">Media yang digunakan untuk publikasi visi, misi, dan unggulan dan laporan sosialisasi.</li>\r\n<li class="MsoNormal">Dokumen rencana strategi (renstra) dan rencana operasional (renop)</li>\r\n</ul>', '2025-10-22 01:24:10', '2025-10-22 01:24:10', 17),
	(35, '', '<p>Capaian Pembelajaran dalam Kurikulum</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana cara merancang dan mengembangkan capaian pembelajaran lulusan dan capaian pembelajaran mata kuliah pada program pendidikan profesi Ners</li>\r\n<li class="MsoNormal">Bagaimana keterlibatan pemangku kepentingan dalam pengembangan kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana keterkaitan capaian pembelajaran lulusan dengan karier lulusan di masyarakat?</li>\r\n<li class="MsoNormal">Bagaimana memastikan capaian pembelajaran yang dipilih sesuai dengan konteks sosial dari wilayah program studi pendidikan profesi Ners?</li>\r\n</ol>', '2025-10-23 02:41:31', '2025-10-23 02:41:31', 18),
	(36, '', '<p>Struktur Kurikulum</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana penerapan prinsip pengembangan struktur kurikulum program studi pendidikan profesi Ners?</li>\r\n<li class="MsoNormal">Bagaimana keterkaitan berbagai disiplin ilmu yang tercakup dalam kurikulum pendidikan profesi Ners?</li>\r\n<li class="MsoNormal">Bagaimana struktur kurikulum dipilih? Sejauh mana model tersebut selaras dengan regulasi nasional?</li>\r\n<li class="MsoNormal">Bagaimana struktur kurikulum mendukung visi, misi dan unggulan program studi pendidikan profesi Ners?</li>\r\n</ol>', '2025-10-23 02:43:12', '2025-10-23 02:43:12', 18),
	(37, '', '<p>Isi Kurikulum</p>', '<ol>\r\n<li>\r\n<p class="MsoNormal">Bagaimana Program Studi bertanggung jawab untuk menentukan isi kurikulum?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana isi kurikulum ditentukan?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Elemen-elemen apa saja dari ilmu biomedis dasar yang dimasukkan dalam kurikulum? Bagaimana kedalaman dan keluasan dari pilihan yang dibuat serta waktu yang dialokasikan untuk elemen elemen ini?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Elemen-elemen ilmu dan keterampilan keperawatan dasar serta keperawatan klinis apa saja yang tercakup dalam kurikulum? Bagaimana menentukan alokasi waktu dan nilai kredit dari elemen-elemen tersebut?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Elemen-elemen apa saja dari Ilmu perilaku, etik dan legal keperawatan serta sosial humaniora yang relevan dengan konteks dan budaya lokal yang dimasukkan dalam kurikulum ? Bagaimana pilihan dan alokasi waktu untuk elemen tersebut?</p>\r\n<p class="MsoNormal">&nbsp;</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana elemen-elemen dari Ilmu sistem kesehatan termasuk sistem pelayanan kesehatan yang dimasukkan ke dalam kurikulum?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana elemen dari ilmu seni mencakup filsafat, sejarah, seni, dan spiritualitas yang dimasukkan ke dalam kurikulum? Bagaimana pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana mahasiswa mengenal bidang-bidang tertentu yang tidak banyak dibahas atau tidak tercakup dalam kurikulum?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana PS memodifikasi isi kurikulum yang berkaitan dengan kemajuan dan perkembangan ilmu pengetahuan dan teknologi?</p>\r\n</li>\r\n<li>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p class="MsoNormal">Bagaimana prinsip metode ilmiah dan penelitian kesehatan keperawatan dibahas dalam kurikulum?</p>\r\n</li>\r\n</ol>', '2025-10-23 02:47:57', '2025-10-23 02:47:57', 18),
	(38, '', '<p>Metode dan Pengalaman Belajar</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana mekanisme dan prinsip apa yang mendasari pemilihan metode dan pengalaman pembelajaran yang digunakan dalam kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana pendistribusian metode dan pengalaman pembelajaran di seluruh kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana program studi pendidikan profesi Ners menyediakan pengalaman klinis yang diperlukan mahasiswa untuk mencapai tujuan pembelajaran?</li>\r\n<li class="MsoNormal">Bagaimana penerapan metode dan pengalaman pembelajaran yang diberikan kepada mahasiswa sesuai dengan konteks, sumber daya, dan kearifan lokal?</li>\r\n<li class="MsoNormal">Bagaimana PS memastikan bahwa perlu untuk menambah atau mengganti pengajaran di kelas dengan metode pembelajaran jarak jauh atau distributed learning (distance-learning)? Jika ya, bagaimana program studi memastikan bahwa metode ini menawarkan tingkat pendidikan dan pelatihan yang memadai?</li>\r\n</ol>', '2025-10-23 02:50:10', '2025-10-23 02:50:10', 18),
	(39, '', '<p>Dokumen Pendukung</p>', '<ul>\r\n<li class="MsoNormal">Notulen rapat komite kurikulum untuk merumuskan capaian pembelajaran lulusan setiap mata kuliah (termasuk pengetahuan, keterampilan, dan perilaku) berdasarkan visi, misi, dan unggulan program studi. Hasilnya dapat diukur dengan menggunakan penilaian yang sesuai.</li>\r\n<li class="MsoNormal">Notulen rapat pelibatan pemangku kepentingan internal dan eksternal.</li>\r\n<li class="MsoNormal">Buku kurikulum (kurikulum: prinsip, isi, urutan), peta kompetensi, Rencana Pembelajaran Semester (RPS), hasil pembelajaran, metode pendidikan, penilaian.</li>\r\n<li class="MsoNormal">Daftar penempatan mahasiswa untuk orientasi pembelajaran klinik profesional ners (early clinical exposure) pada tahap akademik dan praktek klinik profesional mahasiswa ners tahap profesi.</li>\r\n<li class="MsoNormal">Daftar wahana praktek yang digunakan dan memenuhi persyaratan praktek klinik profesional mahasiswa ners.</li>\r\n<li class="MsoNormal">Modul panduan praktek klinik profesional mahasiswa ners</li>\r\n<li class="MsoNormal">Notulen rapat komite kurikulum tentang metode pendidikan, telaah kurikulum, evaluasi dan peninjauan kurikulum</li>\r\n</ul>', '2025-10-23 02:53:47', '2025-10-23 02:53:47', 18),
	(40, '', '<p>Kebijakan dan Sistem Penilaian</p>', '<ol>\r\n<li>Bagaimana penilaian capaian pembelajaran lulusan yang digunakan oleh PS pendidikan profes ners?</li>\r\n<li>Bagaimana keputusan dibuat mengenai transparansi penilaian dan waktunya?</li>\r\n<li>Bagaimana penilaian diintegrasikan dan dikoordinasikan pada berbagai capaian pembelajaran dan kurikulum?</li>\r\n</ol>\r\n<p>&nbsp;</p>', '2025-10-23 03:10:51', '2025-10-23 03:10:51', 19),
	(41, '', '<p>Penilaian dalam Mendukung Pembelajaran</p>', '<ol>\r\n<li>Bagaimana penilaian yang dilakukan kepada mahasiswa PS pendidikan profesi Ners dalam mencapai capaian pembelajaran?</li>\r\n<li>Bagaimana cara mengindentifikasi mahasiswa dari hasil penilaian yang membutuhkan bantuan tambahan?</li>\r\n<li>Bagaimana mahasiswa mendapatkan supervisi dan pengarahan oleh pembimbing klinik dalam mencapai capaian pembelajaran klinik?</li>\r\n<li>Sistem dukungan apa yang dapat ditawarkan kepada mahasiswa yang teridentifikasi memiliki kebutuhan tambahan?</li>\r\n</ol>\r\n<p>&nbsp;</p>', '2025-10-23 03:13:56', '2025-10-23 03:13:56', 19),
	(42, '', '<p>Penilaian untuk mendukung pengambilan keputusan</p>', '<ol>\r\n<li>Bagaimana blueprint (cetak biru) dikembangkan untuk ujian?</li>\r\n<li>bagaimana standar (nilai kelulusan) ditetapkan pada ujian sumaatif?</li>\r\n<li>Bagaimana mekanisme banding mengenai hasil penilaian yang tersedia bagi mahasiswa?</li>\r\n<li>Bagaimana cara memberikan informasi kepada mahasiswa dan pemangku kepentingan lainya, mengenai isi, metode, dan kualitas penilaian?</li>\r\n<li>Bagaimana penilaian digunakan sebagai pedoman untuk menentukan perkembangan pembelajaran mahasiswa?</li>\r\n</ol>', '2025-10-23 03:16:13', '2025-10-23 03:16:13', 19),
	(43, '', '<p>Dokumen pendukung</p>', '<ol>\r\n<li>Prosedur operasional standar penilaian</li>\r\n<li>Rubrik penialain</li>\r\n<li>Daftar nilai mahasiswa</li>\r\n<li>KHS dan transkrip nilai</li>\r\n<li>Soal</li>\r\n<li>Prosedur mekanisme banding</li>\r\n<li>dokumen hasil UKNI dan UKNI OSCE</li>\r\n</ol>', '2025-10-23 03:18:46', '2025-10-23 03:18:46', 19),
	(44, '', '<p>Lingkungan Kerja dan Belajar Mahasiswa</p>', '<ol>\r\n<li>Bagaimana PS menghitung dan menentukan beban dan jam kerja pembelajaran/praktek profesi?</li>\r\n<li>Bagaimana PS menerapkan rencana kerja kegiatan mahasiswa, penyediaan layanan, pendidikan, dan program keselamatan kepada mahasiswa ditetapkan, disosialisasikan, dan dilaksanakan?</li>\r\n<li>Bagaimana PS menetapkan jam kerja minimum dan maksismum yang diperlukan, serta pengaturan hari libur bagi mahasiswa pendidikan profesi ners?</li>\r\n<li>Bagaimana PS mengatur pelaksanaan beban kerja dan tanggung jawab praktik profesi bagi mahasiswa pendidikan profesi ners?</li>\r\n<li>Bagaimanan PS mengatur untuk persiapan dan pelaksanaan ujian dengan tetap menjaga keamanan mahasiswa?</li>\r\n</ol>', '2025-10-23 03:43:53', '2025-10-23 03:43:53', 20),
	(45, '', '<p>Dokumen pendukung</p>', '<ul>\r\n<li>Dokumen hasil survey kepuasan mahasiswa terhadap layanan manajemen</li>\r\n</ul>', '2025-10-23 03:45:14', '2025-10-23 03:45:14', 20),
	(46, '', '<p>Kebijakan Penetapan Dosen</p>', '<ol>\r\n<li>Bagaimana program studi menentukan jumlah dan kualifikasi dosen yang dibutuhkan?</li>\r\n<li>Bagaimana menetapkan jumlah dan kualifikasi dosen agar selaras dengan rancangan, penerapan, dan penjaminan mutu kurikulum?</li>\r\n<li>Bagaimana program studi menyiapkan dosen akademik dan pembimbing klinik pada tatanan klinik untuk melaksanakan kurikulum yang telah disusun?</li>\r\n</ol>', '2025-10-23 03:51:30', '2025-10-23 03:48:02', 21),
	(47, '', '<p>Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol>\r\n<li>Bagaimana program studi menjamin relevansi penelitian dosen dalam mendukung [encapaian visi misi dan unguulan program studi serta monitoring, evaluasi, dan tindak lanjutnya?</li>\r\n<li>Bagaimana program studi mengimplementasikan kegiatan penelitian dosen di UPPS?</li>\r\n<li>Bagaimana integrasi hasil penelitian dalam kegiatan pembelajaran ?</li>\r\n<li>Bagaimana penghargaan dan pengakuan terhadap hasil penelitian dosen?</li>\r\n</ol>', '2025-10-23 03:54:51', '2025-10-23 03:54:51', 21),
	(48, '', '<p>Relevansi Pengabdian Kepada Masyarakat sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol>\r\n<li>Bagaimana program studi menjamin relevansi PkM dosen dalam mendukung pencapaian visi misi dan unguulan program studi serta monitoring, evaluasi, dan tindak lanjutnya?</li>\r\n<li>Bagaimana program studi mengimplementasikan kegiatan PkM dosen di UPPS?</li>\r\n<li>Bagaimana integrasi hasil PkM dalam kegiatan pembelajaran ?</li>\r\n<li>Bagaimana penghargaan dan pengakuan terhadap hasil penelitian dosen?</li>\r\n</ol>', '2025-10-23 03:55:59', '2025-10-23 03:55:59', 21),
	(49, '', '<p>Dokumen Pendukung</p>', '<ol>\r\n<li>Roadmap Penelitian, dan PkM dosen</li>\r\n<li>Bukti penghargaan atau pengakuan atas hasil penelitian (termasuk menerima : HIbah peneltitian, HaKi, dan Paten)</li>\r\n<li>Sertifikat pendidik/Dosen, sertifikat kompetensi</li>\r\n<li>HaKi atau surat pengakuan/penghargaan dari lembaga nasional/internasional</li>\r\n</ol>', '2025-10-23 03:57:58', '2025-10-23 03:57:58', 21),
	(50, '', '<p>Sumber Daya Keterampilan Klinis</p>', '<ol>\r\n<li>Bagaimana program studi menrumuskan kebijakan untuk pelaksanaan metode pembelajarran praktikum dengan simulasi menggunakan pasien sebenarnya?</li>\r\n<li>Bagaimana program studi memastikan sumberdaya pembelajaran praktik klinis dilaksanakan secara konsisten sesuai kurikulum?</li>\r\n<li>Bagaimana program studi menyelenggarakan program pembelajaran praktikum bagi mahasiswa Ners baik praktikum laboratorium dan praktik klinik keperawatan di layanan kesehatan klinik dan komunitas yang mendukung capaian pembelajaran lulusan?</li>\r\n<li>Bagaimana PS menyediakan sumberdaya skill lab (laboratorium keterampilan), yang meliputi pasien simulasi, dan diwahana pembelajaran klinis berupa pasien sebenarnya?</li>\r\n<li>Bagaimana program studi memastikan bahwa mahasiswa memiliki akses yang memadai terhadap fasilitas klinis?</li>\r\n<li>Bagaimana program studi mengatur penempatan mahasiswa dalam praktik klinik sesuai capaian pembelajaran?</li>\r\n<li>Bagaimana program studi melibatkan dosen dan pembimbing klinis dalam rangkaian praktik klinis umum dan khusus sesuai capaian pembelajaran lulusan?</li>\r\n</ol>', '2025-10-23 04:05:13', '2025-10-23 04:05:13', 22),
	(51, '', '<p>Dokumen pendukung</p>', '<ol>\r\n<li>Dafar rumah sakit pendidikan dan wahana praktik</li>\r\n<li>daftar pasien standar dan laporan pelatihanya</li>\r\n<li>daftar pelatihan dan laporan dari dosen klinis dan pendamping</li>\r\n<li>data hasil survei kepuasan atas pelayanan yang diberikan manajemen kepada seluruh pemangku kepentingan (mahasiswa, dosen, pegawai, rekanan, dan pemberi kerja alumni)</li>\r\n<li>data hasil survei kepuasan terhadap kecukupan, kualitas dan akses terhadap fasilitas dan peralatan fisik serta sumber informasi pendidikan dan pelatihan klinis.</li>\r\n</ol>', '2025-10-23 04:08:21', '2025-10-23 04:08:21', 22),
	(52, '', '<p>Pernyataan Visi, Misi, Tujuan dan Strategis</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana rumusan visi, misi, dan unggulan PS Sarjana Kebidanan dan Pendidikan Profesi Bidan ditetapkan?</li>\r\n<li class="MsoNormal">Bagaimana visi, misi, dan unggulan disesuaikan dengan rencana strategis, penjaminan mutu, dan manajemen di PS Sarjana Kebidanan dan Pendidikan Profesi Bidan?</li>\r\n<li class="MsoNormal">Bagaimana pemangku kepentingan terlibat dalam penyusunan visi, misi, dan unggulan PS Sarjana Kebidanan dan Pendidikan Profesi Bidan?</li>\r\n<li class="MsoNormal">Bagaimana visi, misi, dan unggulan menentukan peran PS Sarjana Kebidanan dan Pendidikan Profesi Bidan di dalam masyarakat?</li>\r\n<li class="MsoNormal">Bagaimana kesesuaian visi, misi, dan unggulan dengan filosofi dan pelaksanaan program, serta standar badan akreditasi dan Pemenuhan terhadap Elemen Utama peraturan nasional tentang pendidikan tinggi bidang kesehatan?</li>\r\n<li class="MsoNormal">Bagaimana cara menyosialisasikan visi, misi, dan unggulan PS Sarjana Kebidanan dan Pendidikan Profesi Bidan, analisis tindaklanjutnya?</li>\r\n</ol>', '2025-10-23 04:47:52', '2025-10-23 04:47:52', 23),
	(53, '', '<p>Dokumen Pendukung</p>', '<ol>\r\n<li class="MsoNormal">Notulen rapat pada saat perumusan visi, misi, dan unggulan PS yang berasal dari visi dan misi UPPS</li>\r\n<li class="MsoNormal">Daftar hadir: mahasiswa, dosen, tenaga kependidikan, alumni, pemangku kepentingan, termasuk dokumentasi seperti rekaman foto/video pada saat pertemuan</li>\r\n<li class="MsoNormal">Media yang digunakan untuk publikasi visi, misi, dan unggulan</li>\r\n<li class="MsoNormal">Dokumen rencana strategi (renstra) dan rencana operasional (renop)</li>\r\n<li class="MsoNormal">Dokumen standar pendidikan institusi/UPPS, nasional, dan internasional</li>\r\n</ol>', '2025-10-23 04:49:32', '2025-10-23 04:49:32', 23),
	(54, '', '<p>Capaian Pembelajaran dalam Kurikulum</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana cara merancang dan mengembangkan capaian pembelajaran secara umum dan spesifik</li>\r\n<li class="MsoNormal">Bagaimana capaian pembelajaran disesuaikan dengan kriteria kompetensi yang ditetapkan dan peraturan yang berlaku?</li>\r\n<li class="MsoNormal">Pendekatan apa yang digunakan dalam penyusunan kurikulum dan bagaimana kesesuaiannya terhadap visi, misi, dan unggulan?</li>\r\n<li class="MsoNormal">Bagaimana keterlibatan pemangku kepentingan dalam pengembangan kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menyediakan pengalaman belajar yang diperlukan mahasiswa untuk mencapai tujuan pembelajaran</li>\r\n<li class="MsoNormal">Bagaimana hubungan capaian pembelajaran lulusan dengan karier lulusan di masyarakat (tracer study)</li>\r\n<li class="MsoNormal">Bagaimana memastikan capaian pembelajaran yang dipilih sesuai dengan lingkup sosial dari wilayah PS Sarjana Kebidanan dan Pendidikan Profesi Bidan</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menggunakan hasil evaluasi capaian pembelajaran mahasiswa sebagai dasar untuk mengevaluasi dan merencanakan pengembangan kurikulum selanjutnya?</li>\r\n</ol>', '2025-10-23 04:52:32', '2025-10-23 04:52:32', 24),
	(55, '', '<p>Struktur Kurikulum</p>', '<ol>\r\n<li class="MsoNormal">Apa saja prinsip yang melatarbelakangi desain kurikulum PS Sarjana Kebidanan dan Pendidikan Profesi Bidan?</li>\r\n<li class="MsoNormal">Bagaimana keterkaitan berbagai disiplin ilmu yang tercakup dalam kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana struktur kurikulum dipilih? Sejauh mana model tersebut dibatasi oleh regulasi nasional?</li>\r\n</ol>', '2025-10-23 04:59:36', '2025-10-23 04:59:36', 24),
	(56, '', '<p>Isi Kurikulum</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan bertanggung jawab untuk menentukan isi kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana isi kurikulum ditentukan?</li>\r\n<li class="MsoNormal">Bagaimana elemen dari ilmu kesehatan dasar dan keterampilan praktik bidan dimasukkan ke dalam kurikulum? Bagaimana pilihan-pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut?</li>\r\n<li class="MsoNormal">Bagaimana elemen dari etika hukum dan profesionalism dimasukkan ke dalam kurikulum? Bagaimana pilihan-pilihan yang dibuat dan waktu yang dialokasikan untuk elemen tersebut?</li>\r\n<li class="MsoNormal">Bagaimana elemen dari manajemen dan kepemimpinan dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li class="MsoNormal">Bagaimana elemen dari ilmu kesehatan masyarakat dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut?</li>\r\n<li class="MsoNormal">Bagaimana elemen dari ilmu sosial dan perilaku dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut</li>\r\n<li class="MsoNormal">Bagaimana elemen dari metodologi penelitian dan bukti ilmiah dimasukkan ke dalam kurikulum? Bagaimana pilihan dibuat dan alokasi waktu untuk elemen tersebut</li>\r\n<li class="MsoNormal">Keterampilan klinis kebidanan apa saja yang dibutuhkan oleh semua mahasiswa untuk mendapatkan pengalaman praktik?</li>\r\n<li class="MsoNormal">Bagaimana mahasiswa diajarkan untuk mengambil keputusan klinis yang sesuai dengan menggunakan bukti terbaik yang tersedia?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan mengalokasikan waktu bagi mahasiswa dalam pengaturan praktik klinik yang berbeda?</li>\r\n<li class="MsoNormal">Bagaimana mahasiswa mengenal bidang-bidang tertentu yang tidak banyak dibahas atau tidak tercakup dalam kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan mengembangkan isi kurikulum sesuai dengan kemajuan dan perkembangan ilmu pengetahuan terkini?</li>\r\n<li class="MsoNormal">Bidang apa saja yang bersifat pilihan? Bagaimana bidang pilihan ditentukan?</li>\r\n<li class="MsoNormal">Bagaimana menjamin pembelajaran mahasiswa dalam disiplin ilmu yang tidak memiliki pengalaman khusus?</li>\r\n</ol>\r\n<p class="MsoNormal">&nbsp;</p>', '2025-10-23 05:03:18', '2025-10-23 05:03:18', 24),
	(57, '', '<p>Metode dan Pengalaman Pembelajaran</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana prinsip yang mendasari pemilihan metode dan pengalaman pembelajaran yang digunakan dalam kurikulum ditetapkan?</li>\r\n<li class="MsoNormal">Bagaimana prinsip yang mendasari pemilihan metode dan pengalaman pembelajaran yang digunakan dalam kurikulum ditetapkan?</li>\r\n<li class="MsoNormal">Bagaimana penerapan metode dan pengalaman pembelajaran yang diberikan kepada mahasiswa sesuai dengan lingkup, sumber daya, dan kearifan lokal?</li>\r\n</ol>', '2025-10-23 05:06:35', '2025-10-23 05:06:35', 24),
	(58, '', '<p>Dokumen pendukung</p>', '<ul>\r\n<li class="MsoNormal">Notulen rapat komite kurikulum untuk merumuskan capaian pembelajaran dalam setiap mata kuliah (termasuk pengetahuan, keterampilan, dan perilaku) berdasarkan visi, misi, dan unggulan PS, dan masalah kesehatan utama. Hasilnya dapat diukur dengan menggunakan penilaian yang sesuai</li>\r\n<li class="MsoNormal">&nbsp;Buku kurikulum (kurikulum: prinsip, isi, urutan), peta kompetensi, Rencana Pembelajaran Semester (RPS), hasil pembelajaran, metode pendidikan, dan penilaian pembelajaran</li>\r\n<li class="MsoNormal">Daftar penempatan mahasiswa untuk orientasi pembelajaran klinik profesional (early clinical exposure) pada tahap akademik dan praktik klinik profesional mahasiswa tahap profesi</li>\r\n<li class="MsoNormal">Daftar wahana praktik yang digunakan dan memenuhi persyaratan praktik klinik profesional mahasiswa</li>\r\n</ul>', '2025-10-23 05:09:20', '2025-10-23 05:09:20', 24),
	(59, '', '<p>Kebijakan dan Sistem Penilaian&nbsp;</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana metode penilaian yang digunakan untuk setiap capaian pembelajaran sesuai dengan prinsip penilaian?</li>\r\n<li class="MsoNormal">Bagaimana keputusan dibuat mengenai jumlah penilaian dan waktunya?</li>\r\n<li class="MsoNormal">Bagaimana penilaian diintegrasikan pada berbagai capaian pembelajaran dan kurikulum?</li>\r\n</ol>', '2025-10-23 05:20:43', '2025-10-23 05:20:43', 25),
	(60, '', '<p>Penilaian dalam mendukung pembelajaran</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana mahasiswa dinilai untuk meningkatkan hasil pembelajarannya?</li>\r\n<li class="MsoNormal">Bagaimana cara menilai mahasiswa yang membutuhkan bantuan proses tambahan?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menyediakan sistem pendukung bagi mahasiswa yang teridentifikasi memiliki kebutuhan tambahan?</li>\r\n</ol>', '2025-10-23 05:22:21', '2025-10-23 05:22:21', 25),
	(61, '', '<p>Penilaian untuk mendukung Pengambilan Keputusan</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana cetak biru (blueprint) dikembangkan untuk ujian?</li>\r\n<li class="MsoNormal">Bagaimana standar (nilai kelulusan) ditetapkan pada ujian sumatif?</li>\r\n<li class="MsoNormal">Bagaimana mekanisme banding mengenai hasil penilaian yang tersedia bagi mahasiswa?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarja Kebidanan dan Pendidikan Profesi Bidan memberikan informasi kepada mahasiswa dan pemangku kepentingan lainya, mengenai isi, metode, dan kualitas penilaian?</li>\r\n<li class="MsoNormal">Bagaimana penilaian digunakan sebagai pedoman untuk menentukan perkembangan pembelajaran mahasiswa?</li>\r\n</ol>', '2025-10-23 05:25:18', '2025-10-23 05:25:18', 25),
	(62, '', '<p>Dokumen Pendukung</p>', '<ul>\r\n<li class="MsoNormal">Prosedur operasional standar penilaian</li>\r\n<li class="MsoNormal">Buku catatan mahasiswa (logbook), dokumen revisi strategi pembelajaran: penilaian mahasiswa (evaluasi dan pemantauan kemajuan mahasiswa) dan umpan balik Dosen (strategi mengajar Dosen)</li>\r\n<li class="MsoNormal">Bank Soal dan contoh ujian</li>\r\n<li class="MsoNormal">Cetak biru (blueprint) penilaian</li>\r\n<li class="MsoNormal">Prosedur mekanisme banding</li>\r\n<li class="MsoNormal">Notulen rapat dari pertemuan evaluasi</li>\r\n</ul>', '2025-10-23 05:29:50', '2025-10-23 05:29:50', 25),
	(63, '', '<p>Lingkungan Kerja dan belajar mahasiswa</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana UPPS/PS pendidikan memastikan bahwa wahana praktik memenuhi standar mutu dan keselamatan pasien?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menghitung dan menentukan beban dan jam kerja praktik klinis?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menerapkan rencana kerja kegiatan mahasiswa, penyediaan layanan, pendidikan, dan program keselamatan kepada mahasiswa diputuskan, disebarluaskan, dan ditegakkan?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menetapkan jumlah jam kerja minimum dan maksimum yang diperlukan, pengaturan hari libur, pelaksanaan beban kerja klinis bagi mahasiswa pendidikan profesi?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan mengatur untuk persiapan dan pelaksanaan ujian dengan tetap menjaga keamanan mahasiswa dan pasien?</li>\r\n</ol>', '2025-10-23 05:33:34', '2025-10-23 05:33:34', 27),
	(64, '', '<p>Dokumen pendukung</p>', '<ul>\r\n<li>Dokumen hasil survei kepuasaan mahasiswa terhadap proses pendidikan</li>\r\n<li>Dokumen hasil survei kepuasaan mahasiswa terhadap layanan manajemen</li>\r\n</ul>', '2025-10-23 05:35:29', '2025-10-23 05:35:29', 27),
	(65, '', '<p>Kebijakan penetapan dosen</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menentukan jumlah dan kualifikasi dosen yang dibutuhkan?</li>\r\n<li class="MsoNormal">Bagaimana menetapkan jumlah dan kualifikasi dosen agar selaras dengan rencana, penerapan, dan penjaminan mutu kurikulum?</li>\r\n<li class="MsoNormal">Bagaimana UPPS/PS memastikan dosen dan tenaga kependidikan terhindar dari perundungan?</li>\r\n</ol>', '2025-10-23 05:38:46', '2025-10-23 05:38:46', 28),
	(66, '', '<p>Kinerja dan Perilaku Dosen</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana UPPS/PS menyampaikan informasi akademik dan regulasi kepada dosen baru dan lama?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menyediakan pelatihan orientasi untuk dosen?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menyiapkan dosen dan pembimbing klinik untuk melaksanakan kurikulum yang telah disusun di wahana praktik?</li>\r\n</ol>', '2025-10-23 05:39:56', '2025-10-23 05:39:56', 28),
	(67, '', '<p>Pengembangan Profesional Berkelanjutan untuk Dosen</p>', '<ol>\r\n<li class="MsoNormal">Informasi apa yang diberikan PS kepada dosen baru dan dosen lama tentang pengembangan profesional berkelanjutan?</li>\r\n<li class="MsoNormal">Bagaimana UPPS/PS mengambil tanggung jawab administratif atas penerapan kebijakan pengembangan profesional berkelanjutan dosen?</li>\r\n<li class="MsoNormal">Jaminan finansial apa yang disediakan PS Sarjana Kebidanan dan Pendidikan Profesi Bidan untuk mendukung dosen dalam pengembangan profesional berkelanjutan?</li>\r\n</ol>', '2025-10-23 05:40:50', '2025-10-23 05:40:50', 28),
	(68, '', '<p>Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi&nbsp;</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menjamin relevansi penelitian dosen dalam mendukung pencapaian visi misi dan unggulan PS serta monitoring dan evaluasinya?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan Mengimplementasikan kegiatan penelitian di UPPS?</li>\r\n<li class="MsoNormal">Bagaimana integrasi hasil penelitian dalam kegiatan pembelajaran?</li>\r\n<li class="MsoNormal">Bagaimana penghargaan dan pengakuan terhadap hasil penelitian dosen?</li>\r\n</ol>', '2025-10-23 05:42:44', '2025-10-23 05:42:44', 28),
	(69, '', '<p>Relevansi PkM sesuai dengan Visi dan Unggulan Program Studi&nbsp;</p>', '<ol>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan menjamin relevansi PkM dosen dalam mendukung pencapaian visi misi dan unggulan PS serta monitoring dan evaluasinya?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan Mengimplementasikan kegiatan PkM di UPPS?</li>\r\n<li class="MsoNormal">Bagaimana integrasi hasil PkM dalam kegiatan pembelajaran?</li>\r\n<li class="MsoNormal">Bagaimana penghargaan dan pengakuan terhadap hasil PkM dosen?</li>\r\n</ol>', '2025-10-23 05:43:25', '2025-10-23 05:43:25', 28),
	(70, '', '<p>Dokumen pendukung</p>', '<ul>\r\n<li>Roadmap peneltian dan PkM</li>\r\n<li>Laporan penelitian dosen dan PkM dosen, Publikasi dan sitasinya</li>\r\n<li>Bukti penghargaan atau pengakuan atas hasil penelitian dan PkM (termasuk menerima: Hibah penelitian, Hibah PkM, dan HKI)</li>\r\n<li>Kebijakan integrasi penelitian dan PkM pada pembelajaran</li>\r\n<li>Sertifikat Pendidik/Dosen, Sertifikat Kompetensi, dan Ijazah</li>\r\n<li>HKI atau surat pengakuan/penghargaan dari lembaga nasional/internasional&nbsp;</li>\r\n</ul>', '2025-10-23 05:45:11', '2025-10-23 05:45:11', 28),
	(71, '', '<p>Sumber Daya Keterampilan Klinis</p>', '<ol>\r\n<li class="MsoNormal">Apa saja kesempatan yang diperlukan dan disediakan bagi mahasiswa untuk mempelajari keterampilan klinis?</li>\r\n<li class="MsoNormal">Bagaimana pemanfaatan skill lab (laboratorium keterampilan), pasien simulasi, dan pasien sebenarnya?</li>\r\n<li class="MsoNormal">Apa dasar kebijakan penggunaan pasien simulasi dan pasien sebenarnya?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan memastikan bahwa mahasiswa memiliki akses yang memadai terhadap fasilitas klinis?</li>\r\n<li class="MsoNormal">Apa yang mendasari penempatan mahasiswa di wahana praktik di PS Sarjana Kebidanan dan Pendidikan Profesi Bidan?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan melibatkan dosen dan pembimbing klinis dalam rangkaian stase klinis yang dibutuhkan?</li>\r\n<li class="MsoNormal">Bagaimana PS Sarjana Kebidanan dan Pendidikan Profesi Bidan memastikan penyampaian informasi tentang kurikulum dalam lingkungan klinis secara konsisten?</li>\r\n</ol>', '2025-10-23 05:48:10', '2025-10-23 05:48:10', 29),
	(72, '', '<p>Dokumen pendukung</p>', '<ul>\r\n<li>Daftar wahana praktik</li>\r\n<li>daftar pasien standar dan laporan pelatihanya</li>\r\n<li>daftar pelatihan dan laporanya dari dosen klinis dan pembimbing</li>\r\n<li>Data hasil survei kepuasan atas pelayanan yang diberikan manajemen kepada seluruh pemangku kepentingan (mahasiswa, dosen, pegawai, rekanan, dan pengguna lulusan)</li>\r\n<li>Data hasil survei kepuasan terhadap kecukupan, kualitas dan akses terhadap sarana dan prasarana serta sumber informasi pendidikan dan pelatihan klinis&nbsp;</li>\r\n</ul>', '2025-10-23 05:50:13', '2025-10-23 05:50:13', 29),
	(73, '', '<p>Pernyataan, Visi, Misi, Tujuan dan Strategis</p>', '<ol><li>Bagaimana rumusan visi, misi, dan unggulan program studi\r\nditetapkan?<o:p></o:p></li><li>Bagaimana mekanisme penyusunan visi, misi, dan unggulan\r\nprogram studi dan alasannya?<o:p></o:p></li><li>Bagaimana visi, misi, dan keunggulan menentukan peran\r\nprogram studi di dalam masyarakat?<o:p></o:p></li><li>Bagaimana peran visi, misi, dan unggulan dalam perencanaan, implementasi,\r\nmonitoring, penjaminan mutu, dan manajemen di program studi?<o:p></o:p></li><li>Bagaimana kesesuaian visi, misi, dan unggulan dengan standar\r\ndan peraturan nasional tentang pendidikan tinggi bidang kesehatan?</li><li>Bagaimana cara menyosialisasikan visi, misi, dan unggulan\r\nprogram studi, analisis hasil dan tindaklanjutnya?<o:p></o:p></li></ol>', '2025-10-24 00:59:08', '2025-10-24 00:59:08', 31),
	(74, '', '<p>Dokumen pendukung</p>', '<div><ul><li>Notulen rapat pada saat perumusan visi, misi, dan unggulan\r\nProgram Studi yang berasal dari visi, misi, dan unggulan fakultas dan\r\nuniversitas. Visi, misi, dan unggulan tersebut mencakup peran PS dalam\r\nmeningkatkan derajat kesehatan masyarakat. • Dokumen pengesahan visi dan misi\r\nUPPS dan PS. <o:p></o:p></li></ul>\r\n\r\n<ul><li>Daftar hadir: mahasiswa, dosen, tenaga kependidikan, alumni,\r\npemangku kepentingan, termasuk dokumentasi seperti rekaman foto/video pada saat\r\npertemuan. <o:p></o:p></li></ul>\r\n\r\n<ul><li>&nbsp;Bukti-bukti\r\npencapaian visi, misi dan unggulan <o:p></o:p></li></ul>\r\n\r\n<ul><li>Media yang digunakan untuk publikasi visi, misi, dan\r\nunggulan. <o:p></o:p></li></ul>\r\n\r\n<ul><li>&nbsp;Dokumen rencana\r\nstrategi (renstra) dan rencana operasional (renop)<o:p></o:p></li></ul></div>', '2025-10-24 01:00:24', '2025-10-24 01:00:24', 31),
	(75, '', '<p>Capaian Pembelajaran dalam Kurikulum</p>', '<ol><li>Bagaimana cara merancang dan mengembangkan capaian pembelajaran\r\nlulusan dan capaian pembelajaran mata kuliah?<o:p></o:p></li><li>Siapa saja pemangku kepentingan yang terlibat dalam\r\npengembangan kurikulum?</li><li>Bagaimana hubungan capaian pembelajaran lulusan dengan karir\r\nlulusan di masyarakat?</li><li>Bagaimana memastikan capaian pembelajaran lulusan yang\r\ndipilih sesuai dengan konteks sosial?</li></ol>', '2025-10-24 01:05:24', '2025-10-24 01:05:24', 32),
	(76, '', '<p>Struktur Kurikulum</p>', '<div><ol><li>Bagaimana Pemenuhan Terhadap Elemen Utama penerapan prinsip\r\npengembangan struktur kurikulum program studi?<o:p></o:p></li></ol>\r\n\r\n<ul><li>Bagaimana hubungan antara berbagai disiplin ilmu yang\r\ntercakup dalam kurikulum?<o:p></o:p></li></ul>\r\n\r\n<ul><li>Bagaimana struktur kurikulum dipilih? Sejauh mana model\r\ntersebut selaras dengan regulasi nasional?<o:p></o:p></li></ul>\r\n\r\n<ul><li>Bagaimana desain struktur kurikulum mendukung visi, misi dan\r\nunggulan program studi?<o:p></o:p></li></ul></div>', '2025-10-24 01:06:43', '2025-10-24 01:06:43', 32),
	(77, '', '<p>Isi Kurikulum</p>', '<ol><li>Bagaimana Program Studi bertanggung jawab untuk menentukan\r\nisi kurikulum?</li><li>Bagaimana isi kurikulum ditentukan?</li><li>Elemen apa saja dari ilmu biomedis dan sains farmasi yang\r\ndimasukkan dalam kurikulum? Bagaimana pilihan pilihan yang dibuat dan waktu\r\nyang dialokasikan untuk elemen ini?</li><li>Elemen ilmu pengetahuan dan keterampilan kefarmasian apa\r\nsaja yang tercakup dalam kurikulum? Dalam disiplin keterampilan kefarmasian apa saja, mahasiswa\r\ndiwajibkan untuk mendapatkan pengalaman praktis? Bagaimana mahasiswa\r\ndiajarkan untuk membuat penilaian kefarmasian sesuai dengan data dan bukti yang\r\ntersedia? Bagaimana pilihan yang dibuat dan waktu yang dialokasikan\r\nuntuk elemen ini? Apa dasar alokasi waktu mahasiswa untuk berbagai\r\npraktikum laboratorium dan praktik/early exposure?</li><li>Elemen apa saja dari ilmu perilaku dan sosial yang\r\ndimasukkan dalam kurikulum? Bagaimana pilihan dan alokasi waktu untuk elemen\r\ntersebut?</li><li>Elemen apa saja (jika ada) dari ilmu sistem kesehatan yang\r\ndimasukkan ke dalam kurikulum? Bagaimana pilihan yang dibuat dan waktu\r\nyang dialokasikan untuk elemen ini?</li><li>&nbsp;Elemen apa saja (jika ada) dari humaniora dan seni yang\r\ndimasukkan ke dalam kurikulum? Bagaimana pilihan yang dibuat dan waktu yang\r\ndialokasikan untuk elemen tersebut?</li><li>Bagaimana mahasiswa mengenal/ bidang tertentu yang tidak\r\nbanyak dibahas atau tidak tercakup dalam kurikulum?</li><li>Bagaimana penyesuaian isi kurikulum berkaitan dengan\r\nkemajuan dan perkembangan ilmu pengetahuan dan teknologi?</li><li>Bagaimana prinsip metode ilmiah dan penelitian kefarmasian\r\ndibahas dalam kurikulum?</li></ol><p><br></p>', '2025-10-24 01:09:52', '2025-10-24 01:09:52', 32),
	(78, '', '<p>Metode dan Pengalaman Pembelajaran</p>', '<ol><li>Prinsip apa yang mendasari pemilihan metode dan pengalaman\r\npembelajaran yang digunakan dalam kurikulum ? Bagaimana prinsip tersebut\r\ndiperoleh?</li><li>Bagaimana pendistribusian metode dan pengalaman pembelajaran\r\ndi seluruh kurikulum?</li><li><span style="font-size: 1rem;">Bagaimana metode dan pengalaman pembelajaran yang diberikan\r\nkepada mahasiswa sesuai dengan konteks, sumber daya, dan kearifan lokal?</span></li><li>Apakah tepat atau perlu untuk menambah atau mengganti\r\npengajaran di kelas dengan metode pembelajaran jarak jauh atau distributed\r\nlearning (distance-learning)? Jika ya, bagaimana program studi memastikan bahwa\r\nmetode ini menawarkan tingkat pendidikan dan pelatihan yang memadai?</li><li>Apa yang mendasari penempatan mahasiswa sarjana untuk\r\npelaksanaan early-exposure?</li><li>Bagaimana PS melibatkan dosen dan preseptor?</li><li>Bagaimana Institusi memastikan penerapan dan pelaksanaan\r\nkurikulum dalam early-exposure secara konsisten?</li></ol><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:12:39', '2025-10-24 01:12:39', 32),
	(79, '', '<p>Dokumen pendukung</p>', '<ul><li>Notulen rapat komite kurikulum untuk merumuskan capaian\r\npembelajaran setiap mata kuliah (termasuk pengetahuan, keterampilan, dan\r\nperilaku) berdasarkan visi, misi, dan unggulan program studi. Hasilnya dapat\r\ndiukur dengan menggunakan penilaian yang sesuai. <o:p></o:p></li><li>&nbsp;Buku kurikulum\r\n(kurikulum: prinsip, isi, urutan), peta kompetensi, Rencana Pembelajaran\r\nSemester (RPS), hasil pembelajaran, metode pembelajaran, penilaian. <o:p></o:p></li><li>&nbsp;Daftar wahana praktik\r\ndan tempat yang digunakan sesuai dengan persyaratan yang ditetapkan untuk\r\npenempatan mahasiswa <o:p></o:p></li><li>&nbsp;Notulen rapat komite\r\nkurikulum tentang karakteristik pendidikan, telaah kurikulum, evaluasi dan\r\npeninjauan kurikulum. <o:p></o:p></li></ul><p>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><ul><li>&nbsp;Bukti sertifikasi dan\r\nkualifikasi dosen dan preseptor.<o:p></o:p></li></ul>', '2025-10-24 01:14:35', '2025-10-24 01:14:35', 32),
	(80, '', '<p>Kebijakan dan Sistem Penilaian</p>', '<ol><li>Bagaimana penilaian capaian pembelajaran lulusan yang\r\ndigunakan oleh PS?</li><li><span style="font-size: 1rem;">Bagaimana keputusan dibuat terkait dengan transparansi\r\njumlah dan waktu penilaian?</span></li><li>Bagaimana penilaian diintegrasikan dan dikoordinasikan pada\r\nberbagai capaian pembelajaran dan kurikulum?<o:p></o:p></li></ol><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:18:25', '2025-10-24 01:18:25', 33),
	(81, '', '<p>Penilaian dalam Mendukung Pembelajaran</p>', '<div><ol><li>Bagaimana penilaian yang dilakukan kepada mahasiswa dalam\r\nmencapai capaian pembelajaran?</li><li>Bagaimana cara mengidentifikasi mahasiswa dari hasil\r\npenilaian yang membutuhkan bantuan tambahan?</li><li>Sistem dukungan apa yang dapat ditawarkan kepada para\r\nmahasiswa yang teridentifikasi memiliki kebutuhan tambahan?<o:p></o:p></li></ol></div><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:19:23', '2025-10-24 01:19:23', 33),
	(82, '', '<p>Penilaian untuk Mendukung Pengambilan Keputusan</p>', '<div><ol><li>Bagaimana blueprint (cetak biru) dikembangkan untuk ujian?</li><li>Bagaimana standar (nilai kelulusan) ditetapkan pada ujian\r\nsumatif</li><li>Bagaimana cara memberikan informasi kepada mahasiswa dan\r\npemangku kepentingan lainnya, mengenai isi, metode, kualitas penilaian, dan\r\nmekanisme banding penilaian?</li><li>Bagaimana penilaian digunakan sebagai pedoman untuk\r\nmenentukan perkembangan pembelajaran mahasiswa?</li></ol><p class="MsoNormal"><o:p></o:p></p></div><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:20:25', '2025-10-24 01:20:25', 33),
	(83, '', '<p>Dokumen Pendukung</p>', '<ol><li style="text-align: justify; ">RPS</li><li style="text-align: justify; ">Daftar Nilai Mahasiswa</li><li style="text-align: justify; ">KHS dan atau Transkrip</li><li style="text-align: justify; ">Pedoman Akademik</li><li style="text-align: justify; ">Mekanisme remedial dan konseling</li><li style="text-align: justify; "> Cetak biru\r\n(blueprint) penilaian</li><li style="text-align: justify; "> Prosedur mekanisme\r\nbanding</li><li style="text-align: justify; ">Kebijakan dan\r\nprosedur penilaian sesuai tempat pembelajaran</li></ol>', '2025-10-24 01:31:18', '2025-10-24 01:31:18', 33),
	(84, '', '<p>Lingkungan Kerja dan Belajar Mahasiswa</p>', '<ol><li>Bagaimana institusi pendidikan/UPPS memastikan bahwa\r\nlingkungan kerja dan belajar mahasiswa memenuhi standar mutu dan keselamatan\r\nmahasiswa?</li><li>Bagaimana PS menghitung dan menentukan beban dan jam kerja\r\npembelajaran/praktik?</li><li>Bagaimana PS menerapkan rencana kerja kegiatan mahasiswa,\r\npenyediaan layanan, pendidikan, dan program keselamatan kepada mahasiswa\r\nditetapkan, disosialisasikan, dan dilaksanakan?</li><li>Bagaimana UPPS/PS menetapkan jumlah jam kerja minimum dan\r\nmaksimum yang diperlukan, serta pengaturan hari libur bagi mahasiswa?</li><li>Bagaimana UPPS/PS mengatur pelaksanaan beban kerja dan\r\ntanggung jawab praktik bagi mahasiswa?</li><li>Bagaimana UPPS/PS mengatur untuk persiapan dan pelaksanaan\r\nujian dengan tetap menjaga keamanan mahasiswa?</li></ol>', '2025-10-24 01:37:48', '2025-10-24 01:37:48', 34),
	(85, '', '<p>Dokumen Pendukung</p>', '<ul><li>Dokumen hasil survey kepuasaan mahasiswa terhadap layanan mahasiswa.&nbsp;</li><li> Dokumen hasil survey kepuasaan mahasiswa terhadap layanan manajemen.</li></ul>', '2025-10-24 01:38:35', '2025-10-24 01:38:35', 34),
	(86, '', '<p>Kebijakan Penetapan Dosen</p>', '<ol><li>Bagaimana UPPS/PS menentukan jumlah dan kualifikasi dosen\r\nyang dibutuhkan?</li><li>Bagaimana menetapkan jumlah dan kualifikasi dosen agar\r\nselaras dengan rancangan, penerapan, dan penjaminan mutu kurikulum?</li><li>Bagaimana UPPS memastikan dosen dan tenaga kependidikan\r\nterhindar dari perundungan?</li></ol>', '2025-10-24 01:43:20', '2025-10-24 01:43:20', 35),
	(87, '', '<p>Kinerja Perilaku Dosen</p>', '<ol><li>Bagaimana UPPS dan PS menyiapkan dosen untuk melaksanakan\r\nkurikulum yang telah disusun?</li><li>Bagaimana UPPS dan PS membuat mekanisme untuk menetapkan,\r\nmengatur, dan mengevaluasi kinerja dan perilaku dosen?</li></ol>', '2025-10-24 01:43:47', '2025-10-24 01:43:47', 35),
	(88, '', '<p>Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol><li>Bagaimana upaya PS menjamin relevansi penelitian dosen dalam\r\nmendukung pencapaian visi misi dan unggulan program studi?</li><li>Bagaimana PS mengimplementasikan, monitoring, evaluasi, dan\r\ntindak lanjut kegiatan penelitian di PS?</li><li>Bagaimana integrasi hasil penelitian dalam kegiatan\r\npembelajaran?</li><li>Bagaimana penghargaan dan pengakuan terhadap hasil\r\npenelitian dosen?</li></ol>\r\n\r\n<p class="MsoNormal"><o:p>&nbsp;<br></o:p></p>', '2025-10-24 01:44:29', '2025-10-24 01:44:29', 35),
	(89, '', '<p>Relevansi PkM sesuai dengan Visi dan Unggulan Program Studi</p>', '<ol><li>Bagaimana upaya PS menjamin relevansi PkM dosen dalam\r\nmendukung pencapaian visi misi dan unggulan program studi?</li><li>Bagaimana PS mengimplementasikan, monitoring, evaluasi, dan\r\ntindak lanjut kegiatan PkM di PS?</li><li>Bagaimana integrasi hasil Pkm dalam kegiatan\r\npembelajaran?</li><li>Bagaimana penghargaan dan pengakuan terhadap hasil PkM dosen?</li></ol>\r\n\r\n<p class="MsoNormal"><o:p>&nbsp;<br></o:p></p>', '2025-10-24 01:45:07', '2025-10-24 01:45:07', 35),
	(90, '', '<p>Dokumen Pendukung</p>', '<ol><li>Formulir monitoring dan evaluasi kinerja dosen, sampel formulir yang sudah diisi dari beberap dosen, hasil penilaian kinerja setiap semester</li><li>Bukti penghargaan atau pengakuan atas hasil penelitian (termasuk menerima: Hibah penelitian, \r\nHaKi, dan Paten).&nbsp;</li><li>Sertifikat Pendidik/Dosen, Sertifikat Kompetensi, dan Ijazah</li><li>HaKI atau surat pengakuan/penghargaan dari lembaga nasional/internasional&nbsp;</li></ol>', '2025-10-24 01:46:47', '2025-10-24 01:46:47', 35),
	(91, '', '<p>Kebijakan Seleksi dan Penerimaan Mahasiswa Baru (Maba)</p>', '<ol><li><span style="font-size: 1rem;">Bagaimana menentukan kesesuaian antara kebijakan seleksi dan\r\npenerimaan Maba dengan misi Institusi/UPPS?</span></li><li>Bagaimana agar kebijakan seleksi dan penerimaan mahasiswa\r\nbaru sesuai dengan kebijakan yang ditetapkan oleh pemerintah atau lembaga yang\r\nberwenang?</li><li>Bagaimana kebijakan seleksi dan penerimaan mahasiswa baru\r\nditerapkan di UPPS/PS?</li><li>Bagaimana menyesuaikan kebijakan seleksi dan penerimaan\r\nmahasiswa baru dengan kebutuhan tenaga kerja lokal dan nasional?</li><li>Bagaimana kebijakan seleksi dan penerimaan mahasiswa baru\r\ndirancang agar bersifat adil dan merata, sesuai dengan kebutuhan lokal?</li><li>Bagaimana kebijakan seleksi dan penerimaan mahasiswa baru\r\ndisosialisasikan?</li><li>Bagaimana sistem seleksi dan penerimaan mahasiswa baru,\r\ndikaji dan direvisi secara berkala?</li></ol>', '2025-10-24 01:51:32', '2025-10-24 01:51:32', 37),
	(92, '', '<p>Konseling dan Dukungan Mahasiswa</p>', '<ol><li>Bagaimana layanan akademik dan non akademik termasuk layanan\r\nkonseling pribadi tersedia sesuai dengan kebutuhan mahasiswa? (seperti\r\npenasihat akademik dan karir, bantuan keuangan/ konseling pengelolaan keuangan\r\npendidikan, asuransi kesehatan dan kecelakaan, konseling/ program kesejahteraan\r\npribadi, akses terhadap layanan kesehatan, layanan minat, dan pengembangan\r\nbakat mahasiswa)</li><li>Bagaimana layanan akademik dan non akademik direkomendasikan\r\ndan dikomunikasikan kepada staf dan mahasiswa?</li><li>Bagaimana UPPS/program studi berkolaborasi dengan organisasi\r\nkemahasiswaan untuk membuat, mengembangkan, dan menerapkan layanan akademik dan\r\nnon akademik, baik secara prosedural maupun budaya?</li><li>Bagaimana kelayakan layanan dinilai, dari segi sumber daya\r\nmanusia, keuangan, serta sarana dan prasarana?</li><li>Bagaimana layanan dimonitoring dan dievaluasi secara berkala\r\nbersama perwakilan mahasiswa untuk memastikan relevansi, aksesibilitas, dan\r\nkerahasiaan?</li><li>Bagaimana UPPS/PS mendukung prestasi akademik dan non\r\nakademik mahasiswa?</li></ol><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:52:47', '2025-10-24 01:52:47', 37),
	(93, '', '<p>Keselamatan Mahasiswa</p>', '<div><ol><li>Bagaimana UPPS memberikan perlindungan hukum/peraturan\r\nmahasiswa sehubungan dengan proses pembelajaran, termasuk praktikum di\r\nlaboratorium, dan praktik lapangan/klinis/profesi?</li><li>Bagaimana UPPS/PS menjamin keselamatan fisik dan psikologi\r\nmahasiswa?</li><li>Bagaimana UPPS mempersiapkan kelompok atau individu yang\r\nmempunyai tanggung jawab terhadap keselamatan mahasiswa baik di dalam kampus,\r\ndi wahana praktik, dan lingkungan lainnya?</li><li>Bagaimana UPPS mencegah risiko yang membahayakan keselamatan\r\nmahasiswa dengan mekanisme mengidentifikasi, memitigasi, mencatat, dan\r\nmelaporkan?</li><li>Bagaimana UPPS/PS melakukan langkah-langkah yang diambil\r\nketika risiko keselamatan mahasiswa teridentifikasi?</li></ol></div><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 01:53:35', '2025-10-24 01:53:35', 37),
	(94, '', '<p>Dokumen Pendukung</p>', '<div><ol><li>Peraturan tentang kebijakan seleksi dan penerimaan:\r\nkeselarasan kebijakan seleksi penerimaan mahasiswa baru dengan persyaratan yang\r\nditetapkan oleh pemerintah atau lembaga yang berwenang</li><li>Kebijakan, peraturan, dan prosedur dukungan serta konseling\r\nmahasiswa</li><li>Kebijakan, peraturan, dan prosedur tentang keselamatan\r\nmahasiswa dan keselamatan lingkungan kerja</li><li>Sumber daya manusia, keuangan dam fasilitas pendukung\r\nmahasiswa dan keselamatan lingkungan kerja</li><li>Monitoring dan evaluasi penerapan sistem pendukung\r\nkemahasiswaan</li><li>Dokumen hasil survei kepuasaan mahasiswa terhadap proses Pendidikan</li><li> Dokumen hasil survei\r\nkepuasaan mahasiswa terhadap layanan manajemen</li><li>Dokumen bukti\r\npenanganan, mitigasi, dan pemantauan risiko keselamatan mahasiswa</li><li> Kebijakan, peraturan\r\nmengenai ‘kampus sehat’ termasuk bebas dari kekerasan seksual, perundungan, dan\r\nintoleransi</li><li>Laporan kegiatan promosi</li><li>SPO Sipensimaru</li><li>Laporan Pelaksanaan Sipensimaru</li><li>Monev kegiatan promosi</li></ol><p class="MsoNormal"><o:p></o:p></p></div><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 02:07:38', '2025-10-24 01:56:18', 37),
	(95, '', '<p>DOSEN</p>', '<ol><li>Bagaimana UPPS memastikan dosen dan tenaga kependidikan\r\nterhindar dari perundungan?</li><li>Bagaimana UPPS menyampaikan informasi akademik dan\r\nregulasi kepada dosen baru dan lama?</li><li>Bagaimana UPPS menetapkan mekanisme untuk mengatur dan\r\nmengevaluasi kinerja dan perilaku dosen?</li><li>Bagaimana UPPS menyediakan pelatihan orientasi untuk dosen?</li><li>Bagaimana kebijakan UPPS untuk menjamin kesejahteraan dosen\r\nsecara komprehensif dan kosisten sesuai dengan kebijakan yang berlaku?</li><li>Informasi apa yang diberikan UPPS kepada dosen baru dan\r\ndosen lama mengenai fasilitasi atau pengembangan profesional berkelanjutan?</li><li>Bagaimana UPPS mengambil tanggung jawab administratif atas\r\npenerapan kebijakan pengembangan profesional berkelanjutan dosen?</li><li>Bagaimana mekanisme UPPS dalam mendukung pengembangan\r\nprofessional berkelanjutan?</li></ol>', '2025-10-24 02:13:39', '2025-10-24 02:13:39', 38),
	(96, '', '<p>TENDIK</p>', '<ol><li>Bagaimana UPPS menetapkan jumlah dan kualifikasi tenaga\r\nkependidikan agar memenuhi kebutuhan layanan pelaksanaan tridharma?</li><li>Bagaimana UPPS mengembangkan kemampuan tenaga kependidikan\r\ndalam memenuhi kebutuhan layanan pelaksanaan tridharma dan dalam peningkatan\r\nkarier tenaga kependidikan?</li><li>Bagaimana UPPS memonitoring dan mengevaluasi kinerja tenaga\r\nkependidikan untuk meningkatkan kualitas layanan?</li></ol>', '2025-10-24 02:14:15', '2025-10-24 02:14:15', 38),
	(97, '', '<p>Dokumen Pendukung</p>', '<ol><li>Rencana pengembangan sumber daya manusia (SDM) sesuai dengan\r\nkebutuhan masing-masing disiplin ilmu dan perkembangan ilmu pengetahuan.</li><li>Kebijakan dan prosedur pengembangan SDM (dosen dan tendik).</li><li>Notulen/risalah rapat\r\ndan daftar kehadiran terkait kegiatan pengembangan SDM.</li><li>Formulir monitoring dan evaluasi kinerja dosen, contoh\r\nformulir yang sudah diisi dari beberapa dosen, hasil penilaian kinerja setiap\r\nsemester.</li><li> Laporan program\r\npelatihan orientasi.</li><li>Laporan program pelatihan untuk dosen baru dan lama.&nbsp;</li></ol>\r\n\r\n<p class="MsoNormal"><br></p>', '2025-10-24 02:15:22', '2025-10-24 02:15:22', 38),
	(98, '', '<p>SARPRAS</p>', '<ol><li>Bagaimana UPPS menentukan kecukupan infrastruktur fisik\r\n(sarana dan prasarana) yang disediakan untuk pembelajaran teori dan praktik\r\nyang ditentukan dalam kurikulum?</li><li>Bagaimana UPPS menyediakan sistem informasi yang dibutuhkan\r\nsivitas akademik (dosen, mahasiswa, tendik)?</li><li>Bagaimana UPPS melakukan monitoring dan evaluasi kecukupan\r\ndan aksesibilitas sistem informasi yang disediakan?</li><li>Bagaimana UPPS memastikan bahwa semua mahasiswa, dosen, tendik,\r\ndan pembimbing klinis memiliki akses terhadap informasi yang dibutuhkan?</li></ol><p>DOKUMEN PENDUKUNG SARPRAS:</p><ul><li>Daftar sistem pendukung pembelajaran lainnya. Sistem\r\nManajemen Pembelajaran, kecepatan internet <o:p></o:p></li><li>Kebijakan mengenai Keselamatan dan Kesehatan Kerja civitas\r\nakademika.</li><li>Formulir evaluasi dan umpan balik dari mahasiswa dan staf\r\nakademik serta administrasi untuk sumber informasi yang tersedia</li><li>Fasilitas untuk mengakses sumber informasi dan sumber\r\nbelajar.</li><li>Data hasil survei kepuasan atas pelayanan yang diberikan\r\nmanajemen kepada seluruh pemangku kepentingan (mahasiswa, dosen, pegawai,\r\nrekanan, dan pemberi kerja alumni).</li><li>Data hasil survei kepuasan terhadap kecukupan, kualitas dan\r\nakses terhadap fasilitas dan peralatan fisik serta sumber informasi pendidikan\r\ndan pelatihan klinis.</li><li>Dokumen audit: keuangan dan sarana prasarana.</li><li>Pedoman pengelolaan sarana dan prasarana</li><li>SPO sarana prasarana</li><li><br></li></ul><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 02:19:45', '2025-10-24 02:19:45', 38),
	(99, '', '<p>KEUANGAN</p>', '<div><ol><li>Bagaimana UPPS kebijakan anggaran dan untuk menerapkan\r\nmengalokasikan mendukung pencapaian visi, misi?</li><li>Bagaimana UPPS memastikan ketersediaan sumber daya keuangan\r\nyang cukup dan berkelanjutan untuk mendukung program di semua lokasi?</li><li>Bagaimana UPPS melakukan rencana anggaran perubahan baik\r\nsumber dan atau jumlahnya yang disesuaikan dengan aktivitas program prioritas\r\ndari waktu ke waktu?</li><li>Bagaimana UPPS melakukan monitoring dan evaluasi pengelolaan\r\nsumberdaya keuangan melalui audit internal dan eksternal serta menindaklanjuti\r\nhasil audit tersebut untuk perbaikan dan pengembangan?</li></ol><p>DOKUMEN PENDUKUNG :</p><ul><li>Pedoman pengelolaan keuangan</li><li>Program kerja anggaran dan tahunan</li><li>SOP bagian keuangan</li><li>Dokumen audit keuangan dan sarpras</li><li>Laporan keuangan UPPS dalam waktu 3 tahun terkahir&nbsp;</li></ul></div><p class="MsoNormal"><o:p></o:p></p>', '2025-10-24 02:26:00', '2025-10-24 02:26:00', 38),
	(100, '', '<p>Relevansi Penelitian sesuai dengan Visi dan Unggulan Program Studi</p><p>UPPS memiliki kebijakan terkait yang dilakukan oleh dosen dan mahasiswa</p><p>UPPS memiliki roadmap penelitian yang menjadi rujukan kegiatan penelitian dosen dan mahasiswa \r\nuntuk memastikan relevansi serta kesesuaian dengan visi dan unggulan program studi. Hasil Penelitian \r\ndosen dan mahasiswa diintegrasikan dalam kegiatan pembelajaran dan mendapatkan penghargaan atau \r\npengakuan atas hasil penelitian dalam bentuk Hibah penelitian, HaKi, dan Paten.&nbsp;</p>', '<ol><li>Bagaimana upaya UPPS menjamin \r\nrelevansi penelitian dosen dalam \r\nmendukung pencapaian visi misi dan \r\nunggulan program studi?</li><li>&nbsp;Bagaimana UPPS mengimplementasikan, monitoring, \r\nevaluasi, dan tindak lanjut kegiatan \r\npenelitian di UPPS?</li><li>Bagaimana integrasi hasil penelitian \r\ndalam kegiatan pembelajaran?&nbsp;</li><li>Bagaimana penghargaan dan pengakuan \r\nterhadap hasil penelitian dosen?</li></ol>', '2025-10-24 02:32:56', '2025-10-24 02:30:28', 39),
	(101, '', '<p>Relevansi PkM sesuai dengan Visi dan Unggulan Program Studi</p><p>UPPS memiliki kebijakan terkait yang dilakukan oleh dosen dan mahasiswa</p><p>UPPS memiliki roadmap PkM yang menjadi rujukan kegiatan PkM dosen dan mahasiswa untuk \r\nmemastikan relevansi serta kesesuaian dengan visi dan unggulan program studi. Hasil PkM dosen dan \r\nmahasiswa diintegrasikan dalam kegiatan pembelajaran dan mendapatkan penghargaan atau \r\npengakuan dalam bentuk Hibah PkM, HaKi, dan Paten. Hasil PkM berkontribusi terhadap \r\nkesejahteraan masyarakat dan ilmu pengetahuan.&nbsp;&nbsp;</p>', '<ol><li>Bagaimana upaya UPPS menjamin \r\nrelevansi PkM dosen dalam \r\nmendukung pencapaian visi misi dan \r\nunggulan program studi?</li><li>&nbsp;Bagaimana UPPS mengimplementasikan, monitoring, \r\nevaluasi, dan tindak lanjut kegiatan PkM di UPPS?</li><li>Bagaimana integrasi hasil PkM dalam kegiatan pembelajaran?&nbsp;</li><li>Bagaimana penghargaan dan pengakuan \r\nterhadap hasil PkM dosen?</li></ol>', '2025-10-24 02:32:28', '2025-10-24 02:32:28', 39),
	(102, '', '<p>Dokumen Pendukung</p>', '<ol><li>Roadmap penelitian, dan Pengabdian kepada Masyarakat dosen.&nbsp;</li><li> Laporan penelitian dosen dan PkM dosen serta publikasinya. </li><li>Bukti penghargaan atau pengakuan atas hasil penelitian (termasuk menerima: Hibah penelitian, \r\nHaKi, dan Paten). </li><li>Kebijakan penelitian dan PkM serta integrasinya.</li><li> HaKI atau surat pengakuan/penghargaan dari lembaga nasional/internasional&nbsp;</li></ol>', '2025-10-24 02:33:55', '2025-10-24 02:33:55', 39);
