INSERT INTO `mutu_home_item` (`item_id`, `item_grup`, `item_judul`, `item_isi`, `item_gambar`, `item_ikon`, `item_link`, `item_label_link`, `item_warna`, `item_urutan`, `item_status`, `item_create`, `item_update`) VALUES
	(1, 'kartu', 'PPM', 'Pusat Penjaminan Mutu - kelola dokumen, standar, dan siklus penjaminan mutu.', '', 'bi-shield-check', 'login', 'Login sebagai PPM', '#0f766e', 1, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(2, 'kartu', 'Auditor', 'Anggota PPM yang melaksanakan audit mutu internal terhadap unit kerja.', '', 'bi-clipboard-check', 'login', 'Login sebagai Auditor', '#f59e0b', 2, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(3, 'kartu', 'Auditee', 'Unit kerja atau program studi yang menjadi objek audit mutu internal.', '', 'bi-people', 'login', 'Login sebagai Auditee', '#dc2626', 3, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(4, 'misi', '', 'Mengembangkan dan mengimplementasikan Sistem Penjaminan Mutu Internal (SPMI) secara konsisten dan berkelanjutan sesuai standar nasional pendidikan tinggi.', '', '', '', '', '', 1, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(5, 'misi', '', 'Menyusun, menetapkan, dan mengembangkan standar mutu akademik dan non-akademik sebagai pedoman penyelenggaraan kegiatan institusi.', '', '', '', '', '', 2, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(6, 'misi', '', 'Melaksanakan monitoring, evaluasi, dan Audit Mutu Internal (AMI) secara berkala terhadap program studi dan unit kerja.', '', '', '', '', '', 3, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(7, 'misi', '', 'Mendorong terlaksananya siklus PPEPP (Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan) sebagai budaya mutu di seluruh unit.', '', '', '', '', '', 4, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(8, 'misi', '', 'Meningkatkan kompetensi sumber daya manusia dalam bidang penjaminan mutu melalui pelatihan, pendampingan, dan penyegaran auditor.', '', '', '', '', '', 5, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(9, 'misi', '', 'Mendukung peningkatan mutu Tridharma Perguruan Tinggi dan tata kelola institusi dalam rangka pencapaian akreditasi yang unggul.', '', '', '', '', '', 6, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(10, 'tupoksi', '', 'Merencanakan, melaksanakan, dan mengembangkan penyelenggaraan pendidikan berdasarkan peraturan dan pedoman sistem penjaminan mutu.', '', '', '', '', '', 1, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(11, 'tupoksi', '', 'Menyusun perangkat penjamin mutu.', '', '', '', '', '', 2, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(12, 'tupoksi', '', 'Memonitor dan mengevaluasi pelaksanaan penyelenggaraan Tridharma Perguruan Tinggi.', '', '', '', '', '', 3, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(13, 'tupoksi', '', 'Melaksanakan dan mengembangkan Audit Mutu Internal (AMI).', '', '', '', '', '', 4, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(14, 'tupoksi', '', 'Menyiapkan auditor Audit Mutu Internal.', '', '', '', '', '', 5, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(15, 'tupoksi', '', 'Menyelenggarakan rapat tinjauan manajemen.', '', '', '', '', '', 6, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(16, 'tupoksi', '', 'Memonitor dan mengevaluasi pelaksanaan hasil rapat tinjauan manajemen.', '', '', '', '', '', 7, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(17, 'tupoksi', '', 'Mendampingi proses akreditasi dan reakreditasi institusi, program studi, dan unit pelayanan pendidikan lainnya.', '', '', '', '', '', 8, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(18, 'tupoksi', '', 'Mengembangkan sistem informasi pendukung Sistem Penjaminan Mutu Internal (SPMI).', '', '', '', '', '', 9, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(19, 'sasaran', '', 'Terlaksananya penyelenggaraan pendidikan sesuai dengan kebijakan dan standar SPMI.', '', '', '', '', '', 1, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(20, 'sasaran', '', 'Tersusunnya perangkat penjaminan mutu yang lengkap dan mutakhir.', '', '', '', '', '', 2, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(21, 'sasaran', '', 'Terlaksananya monitoring dan evaluasi Tridharma Perguruan Tinggi secara berkala.', '', '', '', '', '', 3, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(22, 'sasaran', '', 'Terlaksananya Audit Mutu Internal (AMI) secara sistematis dan berkelanjutan.', '', '', '', '', '', 4, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(23, 'sasaran', '', 'Tersedianya auditor mutu internal yang kompeten.', '', '', '', '', '', 5, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(24, 'sasaran', '', 'Terselenggaranya Rapat Tinjauan Manajemen (RTM) secara rutin.', '', '', '', '', '', 6, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(25, 'sasaran', '', 'Terlaksananya tindak lanjut hasil Rapat Tinjauan Manajemen.', '', '', '', '', '', 7, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(26, 'sasaran', '', 'Terlaksananya pendampingan akreditasi dan reakreditasi secara optimal.', '', '', '', '', '', 8, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(27, 'sasaran', '', 'Berkembangnya sistem informasi pendukung SPMI yang efektif.', '', '', '', '', '', 9, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(28, 'slider', 'Personel Pusat Penjaminan Mutu', '', 'assets/assets/images/personil.jpg', '', '', '', '', 1, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54'),
	(29, 'slider', 'Kegiatan Audit Mutu Internal', '', 'assets/assets/images/personil2.jpg', '', '', '', '', 2, 1, '2026-10-01 10:32:54', '2026-10-01 10:32:54');
