	(18, 'akses_deskripsi', 'akses', 'Deskripsi', 'textarea', 'Setiap pengguna memiliki hak akses yang berbeda. Silakan masuk menggunakan akun yang telah diberikan oleh Pusat Penjaminan Mutu.', 18, '2026-10-01 10:32:54'),
	(19, 'profil_judul', 'profil', 'Judul Section', 'text', 'Profil Pusat Penjaminan Mutu', 19, '2026-10-01 10:32:54'),
	(20, 'profil_ringkas', 'profil', 'Paragraf Pembuka', 'textarea', '<strong>Pusat Penjaminan Mutu (PPM) STIK Siti Khadijah</strong> merupakan unit struktural yang bertanggung jawab dalam merencanakan, melaksanakan, mengevaluasi, mengendalikan, dan meningkatkan mutu penyelenggaraan Tridharma Perguruan Tinggi serta tata kelola institusi.', 20, '2026-10-01 10:32:54'),
	(21, 'profil_isi', 'profil', 'Paragraf Kedua', 'textarea', 'PPM berperan sebagai penggerak utama dalam implementasi <strong>Sistem Penjaminan Mutu Internal (SPMI)</strong> secara berkelanjutan. Dalam menjalankan fungsinya, PPM memastikan seluruh kegiatan akademik dan non-akademik berjalan sesuai standar yang ditetapkan, peraturan perundang-undangan, serta kebijakan nasional pendidikan tinggi. Selain itu, PPM menjadi pusat koordinasi pelaksanaan Audit Mutu Internal sebagai instrumen evaluasi dan peningkatan mutu institusi.', 21, '2026-10-01 10:32:54'),
	(22, 'pengelola_judul', 'pengelola', 'Judul Section', 'text', 'Pengelola Pusat Penjaminan Mutu', 22, '2026-10-01 10:32:54'),
	(23, 'pengelola_deskripsi', 'pengelola', 'Deskripsi', 'textarea', 'Susunan personel Pusat Penjaminan Mutu STIK Siti Khadijah yang bertugas menjalankan siklus penjaminan mutu internal.', 23, '2026-10-01 10:32:54'),
	(24, 'pengelola_gambar', 'pengelola', 'Gambar Struktur Pengelola', 'image', 'assets/assets/images/tim.png', 24, '2026-10-01 10:32:54'),
	(25, 'struktur_judul', 'struktur', 'Judul Section', 'text', 'Struktur Organisasi', 25, '2026-10-01 10:32:54'),
	(26, 'struktur_deskripsi', 'struktur', 'Deskripsi', 'textarea', 'Bagan organisasi Pusat Penjaminan Mutu beserta garis koordinasi dengan unit kerja di lingkungan institusi.', 26, '2026-10-01 10:32:54'),
	(27, 'struktur_gambar', 'struktur', 'Gambar Struktur Organisasi', 'image', 'assets/assets/images/strukturorganisasi_fix.png', 27, '2026-10-01 10:32:54'),
	(28, 'visi_judul', 'visi', 'Judul Section', 'text', 'Visi & Misi', 28, '2026-10-01 10:32:54'),
	(29, 'visi_isi', 'visi', 'Isi Visi', 'textarea', 'Menjadi pusat penjaminan mutu yang unggul dalam mengembangkan dan mengawal budaya mutu berkelanjutan guna mendukung terwujudnya <strong>STIK Siti Khadijah</strong> yang berkualitas dan berdaya saing.', 29, '2026-10-01 10:32:54'),
	(30, 'tupoksi_judul', 'tupoksi', 'Judul Section', 'text', 'Tugas Pokok dan Fungsi', 30, '2026-10-01 10:32:54'),
	(31, 'sasaran_judul', 'sasaran', 'Judul Section', 'text', 'Sasaran Mutu', 31, '2026-10-01 10:32:54'),
	(32, 'sasaran_umum_judul', 'sasaran', 'Judul Sasaran Umum', 'text', 'Sasaran Mutu - Umum', 32, '2026-10-01 10:32:54'),
	(33, 'sasaran_umum_isi', 'sasaran', 'Isi Sasaran Umum', 'textarea', 'Mewujudkan terlaksananya Sistem Penjaminan Mutu Internal (SPMI) secara konsisten dan berkelanjutan guna menjamin dan meningkatkan mutu penyelenggaraan Tridharma Perguruan Tinggi serta tata kelola institusi di lingkungan <strong>STIK Siti Khadijah</strong>.', 33, '2026-10-01 10:32:54'),
	(34, 'sasaran_khusus_judul', 'sasaran', 'Judul Sasaran Khusus', 'text', 'Sasaran Mutu - Khusus', 34, '2026-10-01 10:32:54'),
	(35, 'sk_judul', 'dokumen', 'Judul Section', 'text', 'Surat Keputusan', 35, '2026-10-01 10:32:54'),
	(36, 'sk_deskripsi', 'dokumen', 'Deskripsi', 'textarea', 'Dokumen surat keputusan yang berkaitan dengan penyelenggaraan penjaminan mutu.', 36, '2026-10-01 10:32:54'),
	(37, 'berita_judul', 'berita', 'Judul Section', 'text', 'Berita Terbaru', 37, '2026-10-01 10:32:54'),
	(38, 'berita_deskripsi', 'berita', 'Deskripsi', 'textarea', 'Kabar terbaru seputar kegiatan penjaminan mutu.', 38, '2026-10-01 10:32:54'),
